import type { BankQuestion } from "@/lib/bank";

/** Bhakti and Sufi Movements (History): 188 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"history-bhakti-sufi-1","question":"The Bhakti saint Kabir is traditionally regarded as a disciple of:","options":["Vallabhacharya","Ramananda","Chaitanya","Ramanuja"],"answer":1,"explanation":"Tradition makes Kabir a disciple of Ramananda of Varanasi. Vallabhacharya’s best-known follower was Surdas.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भक्ति संत कबीर को परंपरागत रूप से किसका शिष्य माना जाता है?","optionsHi":["वल्लभाचार्य","रामानंद","चैतन्य","रामानुज"],"explanationHi":"परंपरा के अनुसार कबीर वाराणसी के रामानंद के शिष्य थे। वल्लभाचार्य के सबसे प्रसिद्ध अनुयायी सूरदास थे।"},
  {"id":"history-bhakti-sufi-2","question":"Guru Nanak was born in 1469 at Talwandi, which is now known as:","options":["Kartarpur","Anandpur Sahib","Nankana Sahib","Amritsar"],"answer":2,"explanation":"Talwandi Rai Bhoi, near Lahore in present-day Pakistan, is now Nankana Sahib. Kartarpur, on the Ravi, is where Nanak spent his last years.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"गुरु नानक का जन्म 1469 में तलवंडी में हुआ था, जिसे अब किस नाम से जाना जाता है?","optionsHi":["करतारपुर","आनंदपुर साहिब","ननकाना साहिब","अमृतसर"],"explanationHi":"वर्तमान पाकिस्तान में लाहौर के निकट तलवंडी राय भोई अब ननकाना साहिब है। रावी के तट पर स्थित करतारपुर वह स्थान है जहाँ नानक ने अपने अंतिम वर्ष बिताए।"},
  {"id":"history-bhakti-sufi-3","question":"Mirabai, the Rajput princess and poet-saint, was a devotee of:","options":["Rama","Shiva (Ekalinga)","Durga","Krishna"],"answer":3,"explanation":"Mirabai of Merta, married into the Sisodia house of Mewar, composed bhajans to Krishna (Giridhar Gopal). Ekalinga, the Shiva form worshipped by the Mewar rulers, was her in-laws' deity, not hers.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"राजपूत राजकुमारी और कवयित्री-संत मीराबाई किसकी भक्त थीं?","optionsHi":["राम","शिव (एकलिंग)","दुर्गा","कृष्ण"],"explanationHi":"मेड़ता की मीराबाई का विवाह मेवाड़ के सिसोदिया घराने में हुआ था; उन्होंने कृष्ण (गिरधर गोपाल) के भजन रचे। मेवाड़ के शासकों द्वारा पूजित शिव का रूप एकलिंग उनके ससुराल का देवता था, उनका नहीं।"},
  {"id":"history-bhakti-sufi-4","question":"The dargah of Khwaja Moinuddin Chishti, who brought the Chishti order to India, is at:","options":["Ajmer","Delhi","Fatehpur Sikri","Multan"],"answer":0,"explanation":"Khwaja Moinuddin Chishti settled at Ajmer in the late 12th century and died there in 1236. Delhi has the dargah of Nizamuddin Auliya.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"भारत में चिश्ती सिलसिला लाने वाले ख्वाजा मोईनुद्दीन चिश्ती की दरगाह कहाँ है?","optionsHi":["अजमेर","दिल्ली","फतेहपुर सीकरी","मुल्तान"],"explanationHi":"ख्वाजा मोईनुद्दीन चिश्ती 12वीं शताब्दी के अंत में अजमेर में बसे और 1236 में वहीं उनका देहांत हुआ। दिल्ली में निज़ामुद्दीन औलिया की दरगाह है।"},
  {"id":"history-bhakti-sufi-5","question":"Tulsidas wrote the Ramcharitmanas in which language?","options":["Braj Bhasha","Sanskrit","Awadhi","Maithili"],"answer":2,"explanation":"The Ramcharitmanas is in Awadhi. Surdas wrote in Braj Bhasha, and Vidyapati in Maithili.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"तुलसीदास ने रामचरितमानस की रचना किस भाषा में की?","optionsHi":["ब्रज भाषा","संस्कृत","अवधी","मैथिली"],"explanationHi":"रामचरितमानस अवधी में है। सूरदास ने ब्रज भाषा में और विद्यापति ने मैथिली में लिखा।"},
  {"id":"history-bhakti-sufi-6","question":"The devotional songs called abhangas, addressed to Vitthala of Pandharpur, are chiefly associated with:","options":["Surdas","Tukaram","Kabir","Chaitanya"],"answer":1,"explanation":"Tukaram, a 17th-century Marathi saint of the Varkari tradition, is famous for his abhangas to Vitthala.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"पंढरपुर के विट्ठल को संबोधित भक्ति गीत 'अभंग' मुख्यतः किससे जुड़े हैं?","optionsHi":["सूरदास","तुकाराम","कबीर","चैतन्य"],"explanationHi":"वारकरी परंपरा के 17वीं शताब्दी के मराठी संत तुकाराम विट्ठल के प्रति अपने अभंगों के लिए प्रसिद्ध हैं।"},
  {"id":"history-bhakti-sufi-7","question":"Who popularised congregational kirtan and Krishna devotion in Bengal in the early 16th century?","options":["Chaitanya Mahaprabhu","Sankaradeva of Assam","Vallabhacharya","Ramananda"],"answer":0,"explanation":"Chaitanya (1486–1534) of Nabadwip founded Gaudiya Vaishnavism and spread sankirtan. Sankaradeva worked in Assam.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"16वीं शताब्दी के आरंभ में बंगाल में सामूहिक कीर्तन और कृष्ण भक्ति को किसने लोकप्रिय बनाया?","optionsHi":["चैतन्य महाप्रभु","असम के शंकरदेव","वल्लभाचार्य","रामानंद"],"explanationHi":"नवद्वीप के चैतन्य (1486-1534) ने गौड़ीय वैष्णव संप्रदाय की स्थापना की और संकीर्तन का प्रसार किया। शंकरदेव ने असम में कार्य किया।"},
  {"id":"history-bhakti-sufi-8","question":"The Nayanars of the Tamil region were devotees of:","options":["Vishnu","Murugan","Shiva","The Buddha"],"answer":2,"explanation":"The 63 Nayanars were Shaiva saints; the 12 Alvars were devotees of Vishnu.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"तमिल क्षेत्र के नयनार किसके भक्त थे?","optionsHi":["विष्णु","मुरुगन","शिव","बुद्ध"],"explanationHi":"63 नयनार शैव संत थे; 12 आलवार विष्णु के भक्त थे।"},
  {"id":"history-bhakti-sufi-9","question":"The Virashaiva (Lingayat) movement of 12th-century Karnataka was led by:","options":["Basavanna","Madhvacharya","Purandaradasa","Namdev"],"answer":0,"explanation":"Basavanna, a minister at the court of the Kalachuri king Bijjala, led the Virashaiva movement and composed vachanas in Kannada.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"12वीं शताब्दी के कर्नाटक के वीरशैव (लिंगायत) आंदोलन का नेतृत्व किसने किया?","optionsHi":["बसवण्णा","मध्वाचार्य","पुरंदरदास","नामदेव"],"explanationHi":"कलचुरि राजा बिज्जल के दरबार में मंत्री बसवण्णा ने वीरशैव आंदोलन का नेतृत्व किया और कन्नड़ में वचनों की रचना की।"},
  {"id":"history-bhakti-sufi-10","question":"In Sufi terminology, a “khanqah” was:","options":["A collection of a saint’s recorded sayings","The tomb-shrine of a Sufi saint","A Sufi hospice for master and disciples","A gathering for devotional music"],"answer":2,"explanation":"The khanqah was the hospice of a Sufi master (shaikh). The tomb is the dargah, and the musical assembly is sama.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"सूफी शब्दावली में 'खानकाह' क्या था?","optionsHi":["किसी संत की दर्ज की गई उक्तियों का संग्रह","किसी सूफी संत का मकबरा-स्थल","गुरु और शिष्यों का सूफी आश्रम","भक्ति संगीत की सभा"],"explanationHi":"खानकाह सूफी गुरु (शेख) का आश्रम होता था। मकबरा दरगाह है, और संगीत की सभा को समा कहते हैं।"},
  {"id":"history-bhakti-sufi-11","question":"Amir Khusrau, the poet called Tuti-i-Hind, was a disciple of:","options":["Baba Farid","Nizamuddin Auliya","Moinuddin Chishti","Bahauddin Zakariya"],"answer":1,"explanation":"Amir Khusrau was the devoted disciple of the Chishti saint Nizamuddin Auliya of Delhi and is buried near him.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"'तूती-ए-हिंद' कहे जाने वाले कवि अमीर खुसरो किसके शिष्य थे?","optionsHi":["बाबा फरीद","निज़ामुद्दीन औलिया","मोईनुद्दीन चिश्ती","बहाउद्दीन ज़कारिया"],"explanationHi":"अमीर खुसरो दिल्ली के चिश्ती संत निज़ामुद्दीन औलिया के समर्पित शिष्य थे और उन्हीं के निकट दफन हैं।"},
  {"id":"history-bhakti-sufi-12","question":"Sankaradeva, who spread Ekasarana Vaishnavism through namghars and sattras, worked in:","options":["Odisha","Bengal","Manipur","Assam"],"answer":3,"explanation":"Sankaradeva (15th–16th century) preached in Assam; the sattras (monasteries) and namghars (prayer halls) are his legacy.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"नामघरों और सत्रों के माध्यम से एकशरण वैष्णव धर्म का प्रसार करने वाले शंकरदेव ने कहाँ कार्य किया?","optionsHi":["ओडिशा","बंगाल","मणिपुर","असम"],"explanationHi":"शंकरदेव (15वीं-16वीं शताब्दी) ने असम में उपदेश दिए; सत्र (मठ) और नामघर (प्रार्थना-गृह) उनकी विरासत हैं।"},
  {"id":"history-bhakti-sufi-13","question":"Sharafuddin Yahya Maneri of Bihar, famous for his letters (Maktubat), belonged to which Sufi order?","options":["Chishti","Firdausi","Suhrawardi","Qadiri"],"answer":1,"explanation":"Maneri was the leading saint of the Firdausi silsila, an offshoot of the Suhrawardi order, at Bihar Sharif.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बिहार के शरफुद्दीन याह्या मनेरी, जो अपने पत्रों (मकतूबात) के लिए प्रसिद्ध हैं, किस सूफी सिलसिले के थे?","optionsHi":["चिश्ती","फिरदौसी","सुहरावर्दी","कादिरी"],"explanationHi":"मनेरी बिहार शरीफ में सुहरावर्दी सिलसिले की शाखा फिरदौसी सिलसिले के प्रमुख संत थे।"},
  {"id":"history-bhakti-sufi-14","question":"Shaikh Ahmad Sirhindi, who opposed Akbar’s religious policies and was called Mujaddid Alf-i-Sani, belonged to:","options":["The Chishti order","The Suhrawardi order","The Naqshbandi order","The Firdausi order"],"answer":2,"explanation":"Sirhindi was a disciple of Khwaja Baqi Billah, who brought the orthodox Naqshbandi order to India.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अकबर की धार्मिक नीतियों का विरोध करने वाले और 'मुजद्दिद-ए-अल्फ-ए-सानी' कहे जाने वाले शेख अहमद सरहिंदी किससे संबंधित थे?","optionsHi":["चिश्ती सिलसिला","सुहरावर्दी सिलसिला","नक्शबंदी सिलसिला","फिरदौसी सिलसिला"],"explanationHi":"सरहिंदी ख्वाजा बाकी बिल्लाह के शिष्य थे, जो रूढ़िवादी नक्शबंदी सिलसिले को भारत लाए।"},
  {"id":"history-bhakti-sufi-15","question":"The Gurmukhi script is traditionally said to have been developed and standardised by:","options":["Guru Nanak","Guru Angad","Guru Arjan","Guru Gobind Singh"],"answer":1,"explanation":"Guru Angad, the second Guru, is credited with standardising Gurmukhi, in which Sikh scripture is written.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"परंपरा के अनुसार गुरमुखी लिपि का विकास और मानकीकरण किसने किया?","optionsHi":["गुरु नानक","गुरु अंगद","गुरु अर्जन","गुरु गोविंद सिंह"],"explanationHi":"दूसरे गुरु, गुरु अंगद को गुरमुखी के मानकीकरण का श्रेय दिया जाता है, जिसमें सिख धर्मग्रंथ लिखा गया है।"},
  {"id":"history-bhakti-sufi-16","question":"The city of Ramdaspur, later called Amritsar, was founded by:","options":["Guru Amar Das","Guru Hargobind","Guru Arjan","Guru Ram Das"],"answer":3,"explanation":"The fourth Guru, Ram Das, founded Ramdaspur around 1577; his successor Guru Arjan built the Harmandir Sahib there.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"रामदासपुर नगर, जो बाद में अमृतसर कहलाया, की स्थापना किसने की?","optionsHi":["गुरु अमर दास","गुरु हरगोबिंद","गुरु अर्जन","गुरु राम दास"],"explanationHi":"चौथे गुरु, राम दास ने लगभग 1577 में रामदासपुर की स्थापना की; उनके उत्तराधिकारी गुरु अर्जन ने वहाँ हरमंदिर साहिब बनवाया।"},
  {"id":"history-bhakti-sufi-17","question":"The Pushti Marga, a path of devotion to Krishna based on divine grace, was founded by:","options":["Nimbarkacharya","Ramanujacharya","Vallabhacharya","Madhvacharya"],"answer":2,"explanation":"Vallabhacharya founded the Pushti Marga and taught Shuddhadvaita; Surdas was among his disciples.","difficulty":"hard","source":"UPSC Prelims","questionHi":"दैवी कृपा पर आधारित कृष्ण भक्ति का मार्ग पुष्टिमार्ग किसने स्थापित किया?","optionsHi":["निंबार्काचार्य","रामानुजाचार्य","वल्लभाचार्य","मध्वाचार्य"],"explanationHi":"वल्लभाचार्य ने पुष्टिमार्ग की स्थापना की और शुद्धाद्वैत का उपदेश दिया; सूरदास उनके शिष्यों में थे।"},
  {"id":"history-bhakti-sufi-18","question":"In Sufi thought, “fana” means:","options":["The annihilation of the self in God","A spiritual retreat of forty days","The chain of succession of masters","The renunciation of worldly property"],"answer":0,"explanation":"Fana is the passing away of the self in God. The forty-day retreat is chilla, and the chain of masters is the silsila.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सूफी चिंतन में 'फना' का क्या अर्थ है?","optionsHi":["ईश्वर में स्वयं का विलय","चालीस दिन का आध्यात्मिक एकांतवास","गुरुओं की उत्तराधिकार शृंखला","सांसारिक संपत्ति का त्याग"],"explanationHi":"फना ईश्वर में स्वयं का विलीन हो जाना है। चालीस दिन का एकांतवास चिल्ला है, और गुरुओं की शृंखला सिलसिला है।"},
  {"id":"history-bhakti-sufi-19","question":"Lal Ded (Lalleshwari), whose sayings are called vakhs, was a mystic poet of:","options":["Kashmir","Punjab","Gujarat","Assam"],"answer":0,"explanation":"Lal Ded was a 14th-century Kashmiri Shaiva mystic; her vakhs are among the earliest works of Kashmiri literature.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"लल्ल द्यद (ललेश्वरी), जिनकी उक्तियाँ 'वाख' कहलाती हैं, किस क्षेत्र की रहस्यवादी कवयित्री थीं?","optionsHi":["कश्मीर","पंजाब","गुजरात","असम"],"explanationHi":"लल्ल द्यद 14वीं शताब्दी की कश्मीरी शैव रहस्यवादी थीं; उनके वाख कश्मीरी साहित्य की सबसे आरंभिक रचनाओं में हैं।"},
  {"id":"history-bhakti-sufi-20","question":"Which Maharashtrian saint of Pandharpur has hymns included in the Guru Granth Sahib?","options":["Tukaram","Jnaneshwar","Eknath","Namdev"],"answer":3,"explanation":"Namdev’s compositions are included in the Guru Granth Sahib along with those of Kabir, Ravidas and Baba Farid.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पंढरपुर के किस महाराष्ट्रीय संत के भजन गुरु ग्रंथ साहिब में सम्मिलित हैं?","optionsHi":["तुकाराम","ज्ञानेश्वर","एकनाथ","नामदेव"],"explanationHi":"नामदेव की रचनाएँ कबीर, रविदास और बाबा फरीद की रचनाओं के साथ गुरु ग्रंथ साहिब में सम्मिलित हैं।"},
  {"id":"history-bhakti-sufi-21","question":"According to tradition, Mirabai regarded which saint as her guru?","options":["Kabir","Ravidas","Tulsidas","Chaitanya"],"answer":1,"explanation":"Tradition holds that Mirabai took Ravidas (Raidas), a leather-worker saint of Varanasi, as her guru.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"परंपरा के अनुसार मीराबाई किस संत को अपना गुरु मानती थीं?","optionsHi":["कबीर","रविदास","तुलसीदास","चैतन्य"],"explanationHi":"परंपरा के अनुसार मीराबाई ने वाराणसी के चर्मकार संत रविदास (रैदास) को अपना गुरु बनाया।"},
  {"id":"history-bhakti-sufi-22","question":"The Periya Puranam, the hagiography of the 63 Nayanars, was composed by:","options":["Sekkizhar","Nathamuni","Kamban","Appar"],"answer":0,"explanation":"Sekkizhar wrote the Periya Puranam in the reign of the Chola king Kulottunga II. Nathamuni compiled the Alvar hymns, and Kamban wrote the Tamil Ramayana.","difficulty":"hard","source":"UPSC Prelims","questionHi":"63 नयनारों की जीवनी 'पेरिय पुराणम्' की रचना किसने की?","optionsHi":["सेक्किलार","नाथमुनि","कंबन","अप्पर"],"explanationHi":"सेक्किलार ने चोल राजा कुलोत्तुंग द्वितीय के शासनकाल में पेरिय पुराणम् लिखा। नाथमुनि ने आलवारों के भजनों का संकलन किया, और कंबन ने तमिल रामायण लिखी।"},
  {"id":"history-bhakti-sufi-23","question":"Akka Mahadevi, whose vachanas in Kannada are addressed to Chennamallikarjuna, belonged to:","options":["The Varkari tradition","The Virashaiva movement","The Alvar tradition","The Kashmir Shaiva school"],"answer":1,"explanation":"Akka Mahadevi was a 12th-century Virashaiva saint, a contemporary of Basavanna.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"अक्क महादेवी, जिनके कन्नड़ वचन चेन्नमल्लिकार्जुन को संबोधित हैं, किससे संबंधित थीं?","optionsHi":["वारकरी परंपरा","वीरशैव आंदोलन","आलवार परंपरा","कश्मीर शैव संप्रदाय"],"explanationHi":"अक्क महादेवी 12वीं शताब्दी की वीरशैव संत थीं, जो बसवण्णा की समकालीन थीं।"},
  {"id":"history-bhakti-sufi-24","question":"The Chishti saint whose verses are included in the Guru Granth Sahib and whose shrine is at Pakpattan was:","options":["Shaikh Nizamuddin Auliya","Qutbuddin Bakhtiyar Kaki","Fariduddin Ganj-i-Shakar","Shaikh Salim Chishti"],"answer":2,"explanation":"Baba Farid (d. 1265), a Chishti master, composed Punjabi verses included in the Guru Granth Sahib; his dargah is at Pakpattan in Pakistan.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वह चिश्ती संत कौन थे जिनकी रचनाएँ गुरु ग्रंथ साहिब में सम्मिलित हैं और जिनकी दरगाह पाकपट्टन में है?","optionsHi":["शेख निज़ामुद्दीन औलिया","क़ुतुबुद्दीन बख्तियार काकी","फ़रीदुद्दीन गंज-ए-शकर","शेख सलीम चिश्ती"],"explanationHi":"बाबा फरीद (मृत्यु 1265), एक चिश्ती गुरु, ने पंजाबी रचनाएँ कीं जो गुरु ग्रंथ साहिब में सम्मिलित हैं; उनकी दरगाह पाकिस्तान के पाकपट्टन में है।"},
  {"id":"history-bhakti-sufi-25","question":"Match the philosopher with his doctrine: A. Shankaracharya B. Ramanuja C. Madhvacharya D. Nimbarka — 1. Dvaita 2. Advaita 3. Dvaitadvaita 4. Vishishtadvaita","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3"],"answer":2,"explanation":"Shankara – Advaita (non-dualism); Ramanuja – Vishishtadvaita (qualified non-dualism); Madhva – Dvaita (dualism); Nimbarka – Dvaitadvaita (dualism-cum-non-dualism).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"दार्शनिक का उसके सिद्धांत से मिलान कीजिए: A. शंकराचार्य B. रामानुज C. मध्वाचार्य D. निंबार्क — 1. द्वैत 2. अद्वैत 3. द्वैताद्वैत 4. विशिष्टाद्वैत","optionsHi":["A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3"],"explanationHi":"शंकर – अद्वैत; रामानुज – विशिष्टाद्वैत; मध्व – द्वैत; निंबार्क – द्वैताद्वैत।"},
  {"id":"history-bhakti-sufi-26","question":"Arrange these saints in chronological order: 1. Tulsidas 2. Ramanuja 3. Guru Nanak 4. Kabir","options":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"answer":0,"explanation":"Ramanuja (11th–12th century), Kabir (15th century), Guru Nanak (1469–1539), Tulsidas (1532–1623).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन संतों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. तुलसीदास 2. रामानुज 3. गुरु नानक 4. कबीर","optionsHi":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"explanationHi":"रामानुज (11वीं-12वीं शताब्दी), कबीर (15वीं शताब्दी), गुरु नानक (1469-1539), तुलसीदास (1532-1623)।"},
  {"id":"history-bhakti-sufi-27","question":"Which pair of saint and region is NOT correctly matched?","options":["Narsinh Mehta – Gujarat","Purandaradasa – Karnataka","Tukaram – Gujarat","Lal Ded – Kashmir"],"answer":2,"explanation":"Tukaram belonged to Dehu in Maharashtra. Narsinh Mehta (author of “Vaishnav Jan To”) was Gujarati and Purandaradasa a Kannada Haridasa.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"संत और क्षेत्र का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["नरसिंह मेहता – गुजरात","पुरंदरदास – कर्नाटक","तुकाराम – गुजरात","लल्ल द्यद – कश्मीर"],"explanationHi":"तुकाराम महाराष्ट्र के देहू के थे। नरसिंह मेहता ('वैष्णव जन तो') गुजराती थे और पुरंदरदास कन्नड़ भाषी हरिदास थे।"},
  {"id":"history-bhakti-sufi-28","question":"How many of these statements about Kabir are correct? I. His verses include sakhis and pads. II. The Bijak is a compilation of his verses preserved by the Kabirpanth. III. He was a disciple of Vallabhacharya. IV. He composed his verses in classical Sanskrit.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Kabir is linked to Ramananda, not Vallabhacharya, and he wrote in a vernacular mix of Hindi (sadhukkadi), not Sanskrit.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कबीर के बारे में इनमें से कितने कथन सही हैं? I. उनकी रचनाओं में साखियाँ और पद शामिल हैं। II. बीजक उनकी रचनाओं का संकलन है जिसे कबीरपंथ ने सुरक्षित रखा। III. वे वल्लभाचार्य के शिष्य थे। IV. उन्होंने अपनी रचनाएँ शास्त्रीय संस्कृत में कीं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। कबीर का संबंध रामानंद से है, वल्लभाचार्य से नहीं, और उन्होंने संस्कृत में नहीं, हिंदी की मिली-जुली लोकभाषा (सधुक्कड़ी) में लिखा।"},
  {"id":"history-bhakti-sufi-29","question":"How many of these statements about the Sufis are correct? I. The Chishtis generally kept their distance from the court. II. The Suhrawardis accepted state patronage and grants. III. The Chishtis practised sama, listening to music to attain ecstasy. IV. In a silsila, the master was the pir and the disciple the murid.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Suhrawardis, unlike the Chishtis, accepted official posts and grants.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सूफियों के बारे में इनमें से कितने कथन सही हैं? I. चिश्ती सामान्यतः दरबार से दूरी बनाए रखते थे। II. सुहरावर्दी राजकीय संरक्षण और अनुदान स्वीकार करते थे। III. चिश्ती समा करते थे, यानी परमानंद पाने के लिए संगीत सुनना। IV. सिलसिले में गुरु पीर और शिष्य मुरीद होता था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। चिश्तियों के विपरीत, सुहरावर्दी राजकीय पद और अनुदान स्वीकार करते थे।"},
  {"id":"history-bhakti-sufi-30","question":"Assertion (A): Kabir and Guru Nanak composed their teachings in the spoken languages of the people. Reason (R): They wanted their message to reach ordinary people who did not know Sanskrit or Persian.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: the Bhakti saints used vernaculars precisely so that common people could understand them.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कबीर और गुरु नानक ने अपनी शिक्षाएँ लोगों की बोलचाल की भाषाओं में रचीं। कारण (R): वे चाहते थे कि उनका संदेश उन आम लोगों तक पहुँचे जो संस्कृत या फारसी नहीं जानते थे।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है: भक्ति संतों ने लोकभाषाओं का प्रयोग इसीलिए किया कि आम लोग उन्हें समझ सकें।"},
  {"id":"history-bhakti-sufi-31","question":"Assertion (A): Chishti saints used Hindavi and held sama gatherings. Reason (R): The Chishtis believed in accepting state patronage and holding court offices.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true. R is false: the Chishtis kept away from the court and refused official posts; it was the Suhrawardis who accepted state patronage.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): चिश्ती संत हिंदवी का प्रयोग करते थे और समा की सभाएँ करते थे। कारण (R): चिश्ती राजकीय संरक्षण स्वीकार करने और दरबारी पद धारण करने में विश्वास रखते थे।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"A सही है। R गलत है: चिश्ती दरबार से दूर रहते थे और सरकारी पद अस्वीकार करते थे; राजकीय संरक्षण सुहरावर्दी स्वीकार करते थे।"},
  {"id":"history-bhakti-sufi-32","question":"Match the work with its author: A. Sursagar B. Jnaneshwari C. Bijak D. Ramcharitmanas — 1. Kabir 2. Tulsidas 3. Surdas 4. Jnaneshwar","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"Sursagar – Surdas; Jnaneshwari, the Marathi commentary on the Gita – Jnaneshwar; Bijak – Kabir; Ramcharitmanas – Tulsidas.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"रचना का उसके रचनाकार से मिलान कीजिए: A. सूरसागर B. ज्ञानेश्वरी C. बीजक D. रामचरितमानस — 1. कबीर 2. तुलसीदास 3. सूरदास 4. ज्ञानेश्वर","optionsHi":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"explanationHi":"सूरसागर – सूरदास; ज्ञानेश्वरी, गीता पर मराठी टीका – ज्ञानेश्वर; बीजक – कबीर; रामचरितमानस – तुलसीदास।"},
  {"id":"history-bhakti-sufi-33","question":"Arrange in chronological order: 1. Compilation of the Adi Granth 2. Founding of the Khalsa 3. Martyrdom of Guru Tegh Bahadur 4. Martyrdom of Guru Arjan","options":["1-3-4-2","1-4-3-2","4-1-3-2","1-4-2-3"],"answer":1,"explanation":"Adi Granth compiled by Guru Arjan in 1604; Guru Arjan executed in 1606; Guru Tegh Bahadur executed in 1675; Khalsa founded by Guru Gobind Singh in 1699.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन्हें कालक्रम के अनुसार व्यवस्थित कीजिए: 1. आदि ग्रंथ का संकलन 2. खालसा की स्थापना 3. गुरु तेग बहादुर की शहादत 4. गुरु अर्जन की शहादत","optionsHi":["1-3-4-2","1-4-3-2","4-1-3-2","1-4-2-3"],"explanationHi":"आदि ग्रंथ का संकलन गुरु अर्जन ने 1604 में किया; गुरु अर्जन को 1606 में मृत्युदंड दिया गया; गुरु तेग बहादुर को 1675 में मृत्युदंड दिया गया; खालसा की स्थापना गुरु गोविंद सिंह ने 1699 में की।"},
  {"id":"history-bhakti-sufi-34","question":"Who among the following is NOT traditionally counted among the disciples of Ramananda?","options":["Kabir","Ravidas","Sena","Surdas"],"answer":3,"explanation":"Tradition lists Kabir, Ravidas, Sena (a barber) and Dhanna among Ramananda’s disciples. Surdas was a follower of Vallabhacharya.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से किसे परंपरागत रूप से रामानंद के शिष्यों में नहीं गिना जाता?","optionsHi":["कबीर","रविदास","सेना","सूरदास"],"explanationHi":"परंपरा कबीर, रविदास, सेना (एक नाई) और धन्ना को रामानंद के शिष्यों में गिनती है। सूरदास वल्लभाचार्य के अनुयायी थे।"},
  {"id":"history-bhakti-sufi-35","question":"How many of these statements are correct? I. The Alvars were devotees of Vishnu. II. Karaikkal Ammaiyar was an Alvar. III. The Tevaram contains the hymns of the Alvars. IV. The Nalayira Divya Prabandham was compiled by Ramanuja.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Karaikkal Ammaiyar was a Nayanar, the Tevaram holds Nayanar hymns (Appar, Sambandar, Sundarar), and the Nalayira Divya Prabandham was compiled by Nathamuni.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. आलवार विष्णु के भक्त थे। II. कराईक्काल अम्मैयार एक आलवार थीं। III. तेवारम में आलवारों के भजन हैं। IV. नालायिर दिव्य प्रबंधम् का संकलन रामानुज ने किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। कराईक्काल अम्मैयार एक नयनार थीं, तेवारम में नयनारों के भजन हैं (अप्पर, संबंदर, सुंदरर), और नालायिर दिव्य प्रबंधम् का संकलन नाथमुनि ने किया।"},
  {"id":"history-bhakti-sufi-36","question":"Which pair of Sufi saint and the place of his dargah is NOT correctly matched?","options":["Moinuddin Chishti – Ajmer","Nizamuddin Auliya – Delhi","Bahauddin Zakariya – Gulbarga","Salim Chishti – Fatehpur Sikri"],"answer":2,"explanation":"Bahauddin Zakariya, who established the Suhrawardi order in India, is buried at Multan. Gulbarga has the dargah of Gesu Daraz (Bande Nawaz).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सूफी संत और उसकी दरगाह के स्थान का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["मोईनुद्दीन चिश्ती – अजमेर","निज़ामुद्दीन औलिया – दिल्ली","बहाउद्दीन ज़कारिया – गुलबर्गा","सलीम चिश्ती – फतेहपुर सीकरी"],"explanationHi":"भारत में सुहरावर्दी सिलसिले की स्थापना करने वाले बहाउद्दीन ज़कारिया मुल्तान में दफन हैं। गुलबर्गा में गेसू दराज़ (बंदा नवाज़) की दरगाह है।"},
  {"id":"history-bhakti-sufi-37","question":"Arrange these Sufi saints by the year of their death: 1. Shaikh Salim Chishti 2. Nizamuddin Auliya 3. Shaikh Ahmad Sirhindi 4. Moinuddin Chishti","options":["4-2-3-1","2-4-1-3","4-1-2-3","4-2-1-3"],"answer":3,"explanation":"Moinuddin Chishti 1236, Nizamuddin Auliya 1325, Salim Chishti 1572, Ahmad Sirhindi 1624.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन सूफी संतों को उनकी मृत्यु के वर्ष के अनुसार व्यवस्थित कीजिए: 1. शेख सलीम चिश्ती 2. निज़ामुद्दीन औलिया 3. शेख अहमद सरहिंदी 4. मोईनुद्दीन चिश्ती","optionsHi":["4-2-3-1","2-4-1-3","4-1-2-3","4-2-1-3"],"explanationHi":"मोईनुद्दीन चिश्ती 1236, निज़ामुद्दीन औलिया 1325, सलीम चिश्ती 1572, अहमद सरहिंदी 1624।"},
  {"id":"history-bhakti-sufi-38","question":"How many of these statements about Guru Nanak are correct? I. He was born in 1469. II. He set up a settlement at Kartarpur on the Ravi. III. He started the practice of the common kitchen (langar). IV. His hymns were compiled into the Adi Granth by Guru Arjan.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Guru Nanak, born in 1469, settled at Kartarpur on the Ravi and began the langar; Guru Arjan compiled his hymns into the Adi Granth in 1604.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"गुरु नानक के बारे में इनमें से कितने कथन सही हैं? I. उनका जन्म 1469 में हुआ था। II. उन्होंने रावी तट पर करतारपुर में बस्ती बसाई। III. उन्होंने सामूहिक रसोई (लंगर) की प्रथा आरंभ की। IV. उनके भजनों को गुरु अर्जन ने आदि ग्रंथ में संकलित किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। 1469 में जन्मे गुरु नानक ने रावी तट पर करतारपुर में बस्ती बसाई और लंगर आरंभ किया; गुरु अर्जन ने 1604 में उनके भजनों को आदि ग्रंथ में संकलित किया।"},
  {"id":"history-bhakti-sufi-39","question":"Assertion (A): The Lingayats challenged the idea of caste and questioned the theory of rebirth. Reason (R): Basavanna was a minister at the court of the Kalachuri king Bijjala.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but R does not explain A: Basavanna’s office at court is a biographical fact, while the Lingayat stand on caste came from their devotional teaching.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): लिंगायतों ने जाति की धारणा को चुनौती दी और पुनर्जन्म के सिद्धांत पर प्रश्न उठाए। कारण (R): बसवण्णा कलचुरि राजा बिज्जल के दरबार में मंत्री थे।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों सही हैं, लेकिन R, A की व्याख्या नहीं करता: दरबार में बसवण्णा का पद एक जीवनीपरक तथ्य है, जबकि जाति पर लिंगायतों का रुख उनकी भक्ति-शिक्षा से आया।"},
  {"id":"history-bhakti-sufi-40","question":"Which one of the following is NOT counted among the Nirguna Bhakti saints?","options":["Kabir","Ravidas","Guru Nanak","Tulsidas"],"answer":3,"explanation":"Nirguna saints worshipped a formless God. Tulsidas was a Saguna saint devoted to Rama in human form.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"निम्नलिखित में से किसे निर्गुण भक्ति संतों में नहीं गिना जाता?","optionsHi":["कबीर","रविदास","गुरु नानक","तुलसीदास"],"explanationHi":"निर्गुण संत निराकार ईश्वर की उपासना करते थे। तुलसीदास सगुण संत थे, जो मानव रूप में राम के भक्त थे।"},
  {"id":"history-bhakti-sufi-41","question":"The Adi Granth, the scripture of the Sikhs, was compiled in 1604 by:","options":["Guru Nanak","Guru Arjan Dev","Guru Gobind Singh","Guru Angad"],"answer":1,"explanation":"Guru Arjan Dev, the fifth Guru, compiled the Adi Granth in 1604 and installed it in the Harmandir Sahib. Guru Gobind Singh later added Guru Tegh Bahadur's hymns.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"सिखों के धर्मग्रंथ आदि ग्रंथ का संकलन 1604 में किसने किया?","optionsHi":["गुरु नानक","गुरु अर्जन देव","गुरु गोविंद सिंह","गुरु अंगद"],"explanationHi":"पाँचवें गुरु, गुरु अर्जन देव ने 1604 में आदि ग्रंथ का संकलन किया और उसे हरमंदिर साहिब में स्थापित किया। बाद में गुरु गोविंद सिंह ने उसमें गुरु तेग बहादुर के भजन जोड़े।"},
  {"id":"history-bhakti-sufi-42","question":"Who was the tenth and last human Guru of the Sikhs?","options":["Guru Tegh Bahadur","Guru Har Krishan","Guru Gobind Singh","Guru Hargobind"],"answer":2,"explanation":"Guru Gobind Singh (1666–1708) was the tenth Guru; after him the Granth itself became the Guru. Guru Tegh Bahadur, the ninth Guru, was his father.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"सिखों के दसवें और अंतिम देहधारी गुरु कौन थे?","optionsHi":["गुरु तेग बहादुर","गुरु हर कृष्ण","गुरु गोविंद सिंह","गुरु हरगोबिंद"],"explanationHi":"गुरु गोविंद सिंह (1666-1708) दसवें गुरु थे; उनके बाद ग्रंथ स्वयं गुरु बन गया। नौवें गुरु, गुरु तेग बहादुर, उनके पिता थे।"},
  {"id":"history-bhakti-sufi-43","question":"The tomb of the Chishti saint Shaikh Salim Chishti stands in the mosque complex at:","options":["Ajmer Sharif","Mehrauli, Delhi","Fatehpur Sikri","Sirhind, Punjab"],"answer":2,"explanation":"Akbar built Fatehpur Sikri near the hermitage of Shaikh Salim Chishti, whose blessing he credited for the birth of Jahangir; the white marble tomb is in the Jama Masjid courtyard.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"चिश्ती संत शेख सलीम चिश्ती का मकबरा किस स्थान के मस्जिद परिसर में है?","optionsHi":["अजमेर शरीफ","महरौली, दिल्ली","फतेहपुर सीकरी","सरहिंद, पंजाब"],"explanationHi":"अकबर ने शेख सलीम चिश्ती की कुटिया के पास फतेहपुर सीकरी बसाया, जिनके आशीर्वाद से उन्होंने जहाँगीर के जन्म को माना; सफेद संगमरमर का मकबरा जामा मस्जिद के प्रांगण में है।"},
  {"id":"history-bhakti-sufi-44","question":"By occupation, the Bhakti saint Kabir is traditionally described as a:","options":["Weaver","Cobbler","Barber","Tailor"],"answer":0,"explanation":"Kabir was raised in a family of julahas (weavers) at Banaras. Ravidas was a leather worker, Sena a barber and Namdev a tailor.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भक्ति संत कबीर को परंपरागत रूप से उनके पेशे से क्या बताया जाता है?","optionsHi":["जुलाहा","मोची","नाई","दर्ज़ी"],"explanationHi":"कबीर का पालन-पोषण बनारस में जुलाहों के परिवार में हुआ। रविदास चर्मकार थे, सेना नाई और नामदेव दर्ज़ी।"},
  {"id":"history-bhakti-sufi-45","question":"The Jnaneshwari, composed by the Marathi saint Jnaneshwar, is a commentary on:","options":["The Ramayana","The Bhagavad Gita","The Rig Veda","The Bhagavata Purana"],"answer":1,"explanation":"Jnaneshwar wrote the Jnaneshwari (Bhavartha Dipika) in Marathi around 1290 as a commentary on the Bhagavad Gita, making it available to people who knew no Sanskrit.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"मराठी संत ज्ञानेश्वर द्वारा रचित ज्ञानेश्वरी किसकी टीका है?","optionsHi":["रामायण","भगवद्गीता","ऋग्वेद","भागवत पुराण"],"explanationHi":"ज्ञानेश्वर ने लगभग 1290 में मराठी में भगवद्गीता की टीका के रूप में ज्ञानेश्वरी (भावार्थ दीपिका) लिखी, जिससे संस्कृत न जानने वाले भी इसे समझ सके।"},
  {"id":"history-bhakti-sufi-46","question":"The Marathi saint Ekanath is known for his Marathi rendering of:","options":["The Bhagavata Purana","The Bhagavad Gita","Jayadeva's Gita Govinda","The Upanishads"],"answer":0,"explanation":"The 'Ekanathi Bhagavat' is Ekanath's Marathi commentary on the eleventh skandha of the Bhagavata Purana. The Marathi Gita, the Jnaneshwari, is Jnaneshwar's work, which Ekanath only edited.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"मराठी संत एकनाथ किसके मराठी रूपांतरण के लिए जाने जाते हैं?","optionsHi":["भागवत पुराण","भगवद्गीता","जयदेव का गीत गोविंद","उपनिषद"],"explanationHi":"'एकनाथी भागवत' भागवत पुराण के ग्यारहवें स्कंध पर एकनाथ की मराठी टीका है। मराठी गीता, ज्ञानेश्वरी, ज्ञानेश्वर की रचना है, जिसका एकनाथ ने केवल संपादन किया।"},
  {"id":"history-bhakti-sufi-47","question":"Narsinh Mehta, whose bhajan 'Vaishnava jan to' was Gandhiji's favourite, was a saint-poet of:","options":["Maharashtra","Rajasthan","Gujarat","Bengal"],"answer":2,"explanation":"Narsinh Mehta (15th century) of Junagadh is regarded as the first great poet of Gujarati. 'Vaishnava jan to' describes the qualities of a true devotee.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"नरसिंह मेहता, जिनका भजन 'वैष्णव जन तो' गांधीजी का प्रिय था, किस क्षेत्र के संत-कवि थे?","optionsHi":["महाराष्ट्र","राजस्थान","गुजरात","बंगाल"],"explanationHi":"जूनागढ़ के नरसिंह मेहता (15वीं शताब्दी) को गुजराती का पहला महान कवि माना जाता है। 'वैष्णव जन तो' सच्चे भक्त के गुणों का वर्णन करता है।"},
  {"id":"history-bhakti-sufi-48","question":"The town of Anandpur Sahib, where the Khalsa was later founded, was established in 1665 by:","options":["Guru Arjan Dev","Guru Hargobind","Guru Gobind Singh","Guru Tegh Bahadur"],"answer":3,"explanation":"Guru Tegh Bahadur founded Anandpur (first called Chak Nanaki) in 1665. Guru Gobind Singh founded the Khalsa there in 1699.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"आनंदपुर साहिब नगर, जहाँ आगे चलकर खालसा की स्थापना हुई, की स्थापना 1665 में किसने की?","optionsHi":["गुरु अर्जन देव","गुरु हरगोबिंद","गुरु गोविंद सिंह","गुरु तेग बहादुर"],"explanationHi":"गुरु तेग बहादुर ने 1665 में आनंदपुर (पहले चक नानकी) की स्थापना की। गुरु गोविंद सिंह ने वहीं 1699 में खालसा की स्थापना की।"},
  {"id":"history-bhakti-sufi-49","question":"Dadu Dayal, founder of the Dadu Panth and a Nirguna saint, preached mainly in:","options":["Rajasthan","Assam","Tamil Nadu","Kashmir"],"answer":0,"explanation":"Dadu Dayal (1544–1603) settled at Naraina near Jaipur; his followers, the Dadupanthis, are concentrated in Rajasthan.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"दादू पंथ के संस्थापक और निर्गुण संत दादू दयाल ने मुख्यतः कहाँ उपदेश दिए?","optionsHi":["राजस्थान","असम","तमिलनाडु","कश्मीर"],"explanationHi":"दादू दयाल (1544-1603) जयपुर के पास नरायना में बस गए; उनके अनुयायी, दादूपंथी, राजस्थान में केंद्रित हैं।"},
  {"id":"history-bhakti-sufi-50","question":"In the Sufi tradition, the relationship of 'pir' and 'murid' is that of:","options":["Ruler and subject","Master and disciple","Saint and tomb-keeper","Poet and patron"],"answer":1,"explanation":"The pir (also shaikh or murshid) is the spiritual guide; the murid is the disciple who takes an oath of allegiance (bait) to him.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"सूफी परंपरा में 'पीर' और 'मुरीद' का संबंध किस प्रकार का है?","optionsHi":["शासक और प्रजा","गुरु और शिष्य","संत और मकबरे का रखवाला","कवि और संरक्षक"],"explanationHi":"पीर (शेख या मुर्शिद भी) आध्यात्मिक मार्गदर्शक होता है; मुरीद वह शिष्य है जो उसके प्रति निष्ठा की शपथ (बैअत) लेता है।"},
  {"id":"history-bhakti-sufi-51","question":"Chaitanya Mahaprabhu was born in 1486 at:","options":["Puri","Vrindavan","Nabadwip","Mathura"],"answer":2,"explanation":"Chaitanya was born at Nabadwip (Navadvipa) in Bengal. He spent his last years at Puri, which makes Puri a tempting wrong answer.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"चैतन्य महाप्रभु का जन्म 1486 में कहाँ हुआ था?","optionsHi":["पुरी","वृंदावन","नवद्वीप","मथुरा"],"explanationHi":"चैतन्य का जन्म बंगाल के नवद्वीप (नदिया) में हुआ था। उन्होंने अपने अंतिम वर्ष पुरी में बिताए, इसलिए पुरी एक भ्रामक गलत उत्तर है।"},
  {"id":"history-bhakti-sufi-52","question":"In 1708, before his death, Guru Gobind Singh declared which of the following to be the eternal Guru of the Sikhs?","options":["The Khalsa Panth alone","The Guru Granth Sahib","The Akal Takht","The Dasam Granth"],"answer":1,"explanation":"Guru Gobind Singh ended the line of human Gurus and vested the Guruship in the Granth (and the community, the Panth); the scripture is therefore called Guru Granth Sahib.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"1708 में अपनी मृत्यु से पहले गुरु गोविंद सिंह ने निम्नलिखित में से किसे सिखों का शाश्वत गुरु घोषित किया?","optionsHi":["केवल खालसा पंथ","गुरु ग्रंथ साहिब","अकाल तख्त","दशम ग्रंथ"],"explanationHi":"गुरु गोविंद सिंह ने देहधारी गुरुओं की परंपरा समाप्त कर गुरुत्व ग्रंथ (और समुदाय, पंथ) में निहित किया; इसीलिए ग्रंथ को गुरु ग्रंथ साहिब कहा जाता है।"},
  {"id":"history-bhakti-sufi-53","question":"Purandaradasa, honoured as the 'Pitamaha' (father) of Carnatic music, belonged to the:","options":["Virashaiva movement","Haridasa movement","Alvar tradition","Varkari tradition"],"answer":1,"explanation":"Purandaradasa (1484–1564) was a leading Haridasa, the Vaishnava devotional movement of Karnataka. He framed the graded lessons still used to teach Carnatic music.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कर्नाटक संगीत के 'पितामह' के रूप में सम्मानित पुरंदरदास किससे संबंधित थे?","optionsHi":["वीरशैव आंदोलन","हरिदास आंदोलन","आलवार परंपरा","वारकरी परंपरा"],"explanationHi":"पुरंदरदास (1484-1564) कर्नाटक के वैष्णव भक्ति आंदोलन, हरिदास आंदोलन के प्रमुख संत थे। उन्होंने क्रमबद्ध अभ्यास-पाठ बनाए जो आज भी कर्नाटक संगीत सिखाने में प्रयुक्त होते हैं।"},
  {"id":"history-bhakti-sufi-54","question":"The Japji Sahib, the morning prayer that opens the Guru Granth Sahib, was composed by:","options":["Guru Nanak","Guru Angad","Guru Arjan Dev","Guru Gobind Singh"],"answer":0,"explanation":"Japji Sahib is Guru Nanak's composition and begins with the Mul Mantar. Guru Gobind Singh's Jaap Sahib is a different prayer.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"गुरु ग्रंथ साहिब का आरंभ करने वाली प्रातःकालीन प्रार्थना जपजी साहिब की रचना किसने की?","optionsHi":["गुरु नानक","गुरु अंगद","गुरु अर्जन देव","गुरु गोविंद सिंह"],"explanationHi":"जपजी साहिब गुरु नानक की रचना है और मूल मंत्र से आरंभ होती है। गुरु गोविंद सिंह की जाप साहिब एक अलग प्रार्थना है।"},
  {"id":"history-bhakti-sufi-55","question":"Andal, the only woman among the twelve Alvars, composed:","options":["The Tiruvachakam","The Tiruppavai","The Tevaram","The Periya Puranam"],"answer":1,"explanation":"Andal's Tiruppavai (30 verses) and Nachiyar Tirumozhi are addressed to Vishnu. The Tiruvachakam is by Manikkavasagar, the Tevaram is the Nayanars' hymns and the Periya Puranam is by Sekkizhar.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बारह आलवारों में एकमात्र महिला आंडाल ने किसकी रचना की?","optionsHi":["तिरुवाचकम्","तिरुप्पावै","तेवारम्","पेरिय पुराणम्"],"explanationHi":"आंडाल की तिरुप्पावै (30 पद) और नाचियार तिरुमोऴि विष्णु को संबोधित हैं। तिरुवाचकम् मणिक्कवाचकर की है, तेवारम् नयनारों के भजन हैं और पेरिय पुराणम् सेक्किलार का है।"},
  {"id":"history-bhakti-sufi-56","question":"The hymns of the Alvars were compiled as the Nalayira Divya Prabandham in the 10th century by:","options":["Ramanuja","Nathamuni","Sekkizhar","Nambi Andar Nambi"],"answer":1,"explanation":"Nathamuni collected the 4,000 verses of the Alvars. Nambi Andar Nambi compiled the Shaiva Tirumurai, and Sekkizhar wrote the Periya Puranam.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आलवारों के भजनों का नालायिर दिव्य प्रबंधम् के रूप में 10वीं शताब्दी में संकलन किसने किया?","optionsHi":["रामानुज","नाथमुनि","सेक्किलार","नंबी आंडार नंबी"],"explanationHi":"नाथमुनि ने आलवारों के 4,000 पदों का संकलन किया। नंबी आंडार नंबी ने शैव तिरुमुरै का संकलन किया, और सेक्किलार ने पेरिय पुराणम् लिखा।"},
  {"id":"history-bhakti-sufi-57","question":"The Tiruvachakam, a classic of Tamil Shaiva devotion, was composed by:","options":["Appar (Tirunavukkarasar)","Sundarar","Manikkavasagar","Tirujnana Sambandar"],"answer":2,"explanation":"Manikkavasagar wrote the Tiruvachakam; he is not counted among the 63 Nayanars but is revered alongside them. Appar, Sambandar and Sundarar composed the Tevaram hymns instead.","difficulty":"hard","source":"UPSC Prelims","questionHi":"तमिल शैव भक्ति की श्रेष्ठ कृति तिरुवाचकम् की रचना किसने की?","optionsHi":["अप्पर (तिरुनावुक्करसर)","सुंदरर","मणिक्कवाचकर","तिरुज्ञान संबंदर"],"explanationHi":"मणिक्कवाचकर ने तिरुवाचकम् लिखा; उन्हें 63 नयनारों में नहीं गिना जाता, पर उनके साथ पूजा जाता है। अप्पर, संबंदर और सुंदरर ने तेवारम् के भजन रचे।"},
  {"id":"history-bhakti-sufi-58","question":"Majma-ul-Bahrain ('The Mingling of the Two Oceans'), a work comparing Sufi and Vedantic ideas, was written by:","options":["Abul Fazl","Amir Khusrau","Dara Shikoh","Faizi"],"answer":2,"explanation":"Mughal prince Dara Shikoh, a follower of the Qadiri order, wrote Majma-ul-Bahrain (1655) and also had the Upanishads translated into Persian as Sirr-i-Akbar.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सूफी और वेदांती विचारों की तुलना करने वाली कृति 'मजमा-उल-बहरैन' ('दो समुद्रों का संगम') किसने लिखी?","optionsHi":["अबुल फज़ल","अमीर खुसरो","दारा शिकोह","फैज़ी"],"explanationHi":"कादिरी सिलसिले के अनुयायी मुगल राजकुमार दारा शिकोह ने मजमा-उल-बहरैन (1655) लिखी और उपनिषदों का फारसी अनुवाद 'सिर्र-ए-अकबर' के नाम से भी करवाया।"},
  {"id":"history-bhakti-sufi-59","question":"The Rishi order, a Sufi tradition rooted in Kashmir, was founded by:","options":["Shaikh Nuruddin Wali (Nund Rishi)","Mir Sayyid Ali Hamadani","Shah-i-Hamadan's son Mir Muhammad","Baba Farid"],"answer":0,"explanation":"Nuruddin Wali (Nund Rishi, 1377–1438), a younger contemporary of Lal Ded, founded the Rishi order. Mir Sayyid Ali Hamadani brought the Kubrawi order to Kashmir.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कश्मीर में जड़ें रखने वाली सूफी परंपरा ऋषि सिलसिले की स्थापना किसने की?","optionsHi":["शेख नुरुद्दीन वली (नुंद ऋषि)","मीर सैयद अली हमदानी","शाह-ए-हमदान के पुत्र मीर मुहम्मद","बाबा फरीद"],"explanationHi":"लल्ल द्यद के कनिष्ठ समकालीन नुरुद्दीन वली (नुंद ऋषि, 1377-1438) ने ऋषि सिलसिले की स्थापना की। मीर सैयद अली हमदानी कश्मीर में कुबरवी सिलसिला लाए।"},
  {"id":"history-bhakti-sufi-60","question":"Surdas, the blind poet of the Sursagar, is traditionally regarded as a disciple of:","options":["Swami Ramananda","Vallabhacharya","Chaitanya","Nimbarkacharya"],"answer":1,"explanation":"Surdas belonged to Vallabhacharya's Pushti Marga and was one of the Ashtachhap poets. He is not counted among Ramananda's disciples.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सूरसागर के नेत्रहीन कवि सूरदास को परंपरागत रूप से किसका शिष्य माना जाता है?","optionsHi":["स्वामी रामानंद","वल्लभाचार्य","चैतन्य","निंबार्काचार्य"],"explanationHi":"सूरदास वल्लभाचार्य के पुष्टिमार्ग के अनुयायी थे और अष्टछाप कवियों में से एक थे। उन्हें रामानंद के शिष्यों में नहीं गिना जाता।"},
  {"id":"history-bhakti-sufi-61","question":"The philosophy of Chaitanya Mahaprabhu and the Gaudiya Vaishnavas is known as:","options":["Achintya Bhedabheda","Shuddhadvaita","Svabhavika Bhedabheda","Vishishtadvaita"],"answer":0,"explanation":"Achintya Bhedabheda means 'inconceivable difference and non-difference' between God and the soul. Shuddhadvaita is Vallabha's, Svabhavika Bhedabheda (Dvaitadvaita) Nimbarka's and Vishishtadvaita Ramanuja's.","difficulty":"hard","source":"UPSC Prelims","questionHi":"चैतन्य महाप्रभु और गौड़ीय वैष्णवों का दर्शन क्या कहलाता है?","optionsHi":["अचिंत्य भेदाभेद","शुद्धाद्वैत","स्वाभाविक भेदाभेद","विशिष्टाद्वैत"],"explanationHi":"अचिंत्य भेदाभेद का अर्थ है ईश्वर और जीव के बीच 'अचिंत्य भेद और अभेद'। शुद्धाद्वैत वल्लभ का, स्वाभाविक भेदाभेद (द्वैताद्वैत) निंबार्क का और विशिष्टाद्वैत रामानुज का है।"},
  {"id":"history-bhakti-sufi-62","question":"Fawaid-ul-Fuad, a record of the conversations of Nizamuddin Auliya, was compiled by:","options":["Amir Khusrau","Amir Hasan Sijzi","Ziauddin Barani","Nasiruddin Chiragh-i-Dehli"],"answer":1,"explanation":"Amir Hasan Sijzi, a poet and disciple, recorded the saint's sayings in Fawaid-ul-Fuad, a classic of the malfuzat genre. Nasiruddin Chiragh-i-Dehli was Nizamuddin's spiritual successor.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निज़ामुद्दीन औलिया की वार्ताओं का अभिलेख 'फवाइद-उल-फुआद' किसने संकलित किया?","optionsHi":["अमीर खुसरो","अमीर हसन सिज्ज़ी","ज़ियाउद्दीन बरनी","नसीरुद्दीन चिराग-ए-दिल्ली"],"explanationHi":"कवि और शिष्य अमीर हसन सिज्ज़ी ने संत की उक्तियों को 'फवाइद-उल-फुआद' में दर्ज किया, जो मलफूज़ात विधा की एक श्रेष्ठ कृति है। नसीरुद्दीन चिराग-ए-दिल्ली निज़ामुद्दीन के आध्यात्मिक उत्तराधिकारी थे।"},
  {"id":"history-bhakti-sufi-63","question":"The scribe who wrote out the Adi Granth for Guru Arjan Dev in 1604 was:","options":["Bhai Mardana","Baba Buddha","Bhai Gurdas","Bhai Mani Singh"],"answer":2,"explanation":"Bhai Gurdas wrote the original volume at Guru Arjan's dictation. Baba Buddha was its first granthi (custodian), Bhai Mardana was Guru Nanak's rabab player, and Bhai Mani Singh later wrote out the Damdami version.","difficulty":"hard","source":"UPSC Prelims","questionHi":"1604 में गुरु अर्जन देव के लिए आदि ग्रंथ को लिपिबद्ध करने वाले लिपिक कौन थे?","optionsHi":["भाई मरदाना","बाबा बुड्ढा","भाई गुरदास","भाई मनी सिंह"],"explanationHi":"भाई गुरदास ने गुरु अर्जन के बोलने पर मूल ग्रंथ लिखा। बाबा बुड्ढा उसके प्रथम ग्रंथी (संरक्षक) थे, भाई मरदाना गुरु नानक के रबाब वादक थे, और भाई मनी सिंह ने बाद में दमदमी बीड़ लिखी।"},
  {"id":"history-bhakti-sufi-64","question":"The Akal Takht at Amritsar, the seat of temporal authority of the Sikhs, was established by:","options":["Guru Arjan Dev","Guru Hargobind","Guru Har Rai","Guru Gobind Singh"],"answer":1,"explanation":"Guru Hargobind built the Akal Takht in 1606 after his father's execution, wore two swords (miri and piri) and began to arm the community.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"अमृतसर में सिखों की लौकिक सत्ता का केंद्र अकाल तख्त किसने स्थापित किया?","optionsHi":["गुरु अर्जन देव","गुरु हरगोबिंद","गुरु हर राय","गुरु गोविंद सिंह"],"explanationHi":"गुरु हरगोबिंद ने अपने पिता के वध के बाद 1606 में अकाल तख्त बनवाया, दो तलवारें (मीरी और पीरी) धारण कीं और समुदाय को सशस्त्र करना आरंभ किया।"},
  {"id":"history-bhakti-sufi-65","question":"The Anubhava Mantapa, a hall for open spiritual discussion among men and women of all castes, was associated with:","options":["Ramanuja at Srirangam","Basavanna at Kalyana","Madhvacharya at Udupi","Tukaram at Dehu"],"answer":1,"explanation":"Basavanna set up the Anubhava Mantapa at Kalyana (Basavakalyan) in the 12th century; the Lingayat vachana poets, including Akka Mahadevi and Allama Prabhu, took part.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सभी जातियों के स्त्री-पुरुषों के लिए खुली आध्यात्मिक चर्चा के सभागार 'अनुभव मंटप' का संबंध किससे था?","optionsHi":["श्रीरंगम में रामानुज","कल्याण में बसवण्णा","उडुपी में मध्वाचार्य","देहू में तुकाराम"],"explanationHi":"बसवण्णा ने 12वीं शताब्दी में कल्याण (बसवकल्याण) में अनुभव मंटप स्थापित किया; अक्क महादेवी और अल्लम प्रभु सहित लिंगायत वचनकार इसमें सम्मिलित होते थे।"},
  {"id":"history-bhakti-sufi-66","question":"Mirabai was married into the royal family of:","options":["Amber","Marwar","Mewar","Bundi"],"answer":2,"explanation":"Mirabai, a Rathore princess of Merta (Marwar), was married to Bhoj Raj, son of Rana Sanga of Mewar. She later left the court to live as a devotee of Krishna.","difficulty":"hard","source":"SSC CGL · State PSCs","questionHi":"मीराबाई का विवाह किस राजघराने में हुआ था?","optionsHi":["आमेर","मारवाड़","मेवाड़","बूँदी"],"explanationHi":"मेड़ता (मारवाड़) की राठौड़ राजकुमारी मीराबाई का विवाह मेवाड़ के राणा सांगा के पुत्र भोज राज से हुआ था। बाद में उन्होंने दरबार छोड़कर कृष्ण-भक्त का जीवन अपनाया।"},
  {"id":"history-bhakti-sufi-67","question":"Samarth Ramdas, author of the Dasbodh, is traditionally regarded as the spiritual guide of:","options":["Shivaji","Shahu","Baji Rao I","Ranjit Singh"],"answer":0,"explanation":"Samarth Ramdas (1608–81), a devotee of Rama and Hanuman, is linked by tradition with Shivaji. The Dasbodh is his Marathi work of spiritual and practical advice.","difficulty":"hard","source":"SSC CGL · State PSCs","questionHi":"'दासबोध' के रचयिता समर्थ रामदास को परंपरागत रूप से किसका आध्यात्मिक मार्गदर्शक माना जाता है?","optionsHi":["शिवाजी","शाहू","बाजीराव प्रथम","रणजीत सिंह"],"explanationHi":"राम और हनुमान के भक्त समर्थ रामदास (1608-81) को परंपरा शिवाजी से जोड़ती है। दासबोध उनकी आध्यात्मिक और व्यावहारिक उपदेशों की मराठी रचना है।"},
  {"id":"history-bhakti-sufi-68","question":"Match the Sufi order with the saint who established it in India: A. Chishti B. Suhrawardi C. Naqshbandi D. Firdausi — 1. Khwaja Baqi Billah 2. Bahauddin Zakariya 3. Moinuddin Chishti 4. Badruddin Samarqandi","options":["A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1"],"answer":1,"explanation":"Moinuddin Chishti (Ajmer) – Chishti; Bahauddin Zakariya (Multan) – Suhrawardi; Khwaja Baqi Billah (Delhi, Akbar's time) – Naqshbandi; Badruddin Samarqandi – Firdausi, later spread in Bihar by Sharafuddin Yahya Maneri.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सूफी सिलसिले का उस संत से मिलान कीजिए जिसने उसे भारत में स्थापित किया: A. चिश्ती B. सुहरावर्दी C. नक्शबंदी D. फिरदौसी — 1. ख्वाजा बाकी बिल्लाह 2. बहाउद्दीन ज़कारिया 3. मोईनुद्दीन चिश्ती 4. बदरुद्दीन समरकंदी","optionsHi":["A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1"],"explanationHi":"मोईनुद्दीन चिश्ती (अजमेर) – चिश्ती; बहाउद्दीन ज़कारिया (मुल्तान) – सुहरावर्दी; ख्वाजा बाकी बिल्लाह (दिल्ली, अकबर के समय) – नक्शबंदी; बदरुद्दीन समरकंदी – फिरदौसी, जो बाद में बिहार में शरफुद्दीन याह्या मनेरी द्वारा फैलाया गया।"},
  {"id":"history-bhakti-sufi-69","question":"Arrange these Sikh Gurus in the order of their Guruship: 1. Guru Har Rai 2. Guru Hargobind 3. Guru Ram Das 4. Guru Har Krishan","options":["3-1-2-4","2-3-1-4","3-2-4-1","3-2-1-4"],"answer":3,"explanation":"Ram Das was the fourth Guru, Hargobind the sixth, Har Rai the seventh and Har Krishan, the child Guru, the eighth.","difficulty":"very-hard","source":"SSC CGL · State PSCs","questionHi":"इन सिख गुरुओं को उनके गुरुकाल के क्रम में व्यवस्थित कीजिए: 1. गुरु हर राय 2. गुरु हरगोबिंद 3. गुरु राम दास 4. गुरु हर कृष्ण","optionsHi":["3-1-2-4","2-3-1-4","3-2-4-1","3-2-1-4"],"explanationHi":"राम दास चौथे गुरु थे, हरगोबिंद छठे, हर राय सातवें और बाल गुरु हर कृष्ण आठवें।"},
  {"id":"history-bhakti-sufi-70","question":"Match the work with its author: A. Padmavat B. Kirtan Ghosha C. Vinaya Patrika D. Bhaktamal — 1. Tulsidas 2. Nabhadas 3. Malik Muhammad Jayasi 4. Sankaradeva","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"Padmavat (1540) is the Sufi poet Jayasi's Awadhi romance; Kirtan Ghosha is Sankaradeva's Assamese verse; Vinaya Patrika is by Tulsidas; Nabhadas's Bhaktamal gives lives of the Bhakti saints.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"रचना का उसके रचनाकार से मिलान कीजिए: A. पद्मावत B. कीर्तन घोषा C. विनय पत्रिका D. भक्तमाल — 1. तुलसीदास 2. नाभादास 3. मलिक मुहम्मद जायसी 4. शंकरदेव","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-1, C-4, D-2"],"explanationHi":"पद्मावत (1540) सूफी कवि जायसी का अवधी प्रेमाख्यान है; कीर्तन घोषा शंकरदेव की असमिया काव्य रचना है; विनय पत्रिका तुलसीदास की है; नाभादास की भक्तमाल भक्त संतों की जीवनियाँ देती है।"},
  {"id":"history-bhakti-sufi-71","question":"How many of these statements about Chaitanya Mahaprabhu are correct? I. He spent his last years at Puri. II. His Gaudiya followers regard him as Radha and Krishna in one form. III. He composed the Sursagar. IV. He was a disciple of Ramananda.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. The Sursagar is Surdas's work, and Chaitanya's initiation came from Ishvara Puri and Keshava Bharati, not Ramananda. So only two.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चैतन्य महाप्रभु के बारे में इनमें से कितने कथन सही हैं? I. उन्होंने अपने अंतिम वर्ष पुरी में बिताए। II. उनके गौड़ीय अनुयायी उन्हें राधा और कृष्ण का एक संयुक्त रूप मानते हैं। III. उन्होंने सूरसागर की रचना की। IV. वे रामानंद के शिष्य थे।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। सूरसागर सूरदास की रचना है, और चैतन्य की दीक्षा ईश्वर पुरी और केशव भारती से हुई, रामानंद से नहीं। अतः केवल दो।"},
  {"id":"history-bhakti-sufi-72","question":"How many of these statements about Sufi practice are correct? I. The urs marks the death anniversary of a saint, seen as his union with God. II. The murid is the spiritual master of a khanqah. III. A silsila is the chain of spiritual descent from master to disciple. IV. Qawwali grew out of the sama gatherings of the Chishtis.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. The murid is the disciple; the master is the pir or shaikh.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सूफी साधना के बारे में इनमें से कितने कथन सही हैं? I. उर्स किसी संत की पुण्यतिथि है, जिसे उसका ईश्वर से मिलन माना जाता है। II. मुरीद खानकाह का आध्यात्मिक गुरु होता है। III. सिलसिला गुरु से शिष्य तक आध्यात्मिक परंपरा की शृंखला है। IV. कव्वाली चिश्तियों की समा की सभाओं से विकसित हुई।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, III और IV सही हैं। मुरीद शिष्य होता है; गुरु को पीर या शेख कहते हैं।"},
  {"id":"history-bhakti-sufi-73","question":"Assertion (A): Tulsidas is counted among the Saguna Bhakti poets. Reason (R): He worshipped Rama as a personal God with form and attributes.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: Saguna bhakti is devotion to God with attributes (Rama, Krishna), as opposed to Nirguna bhakti to a formless God (Kabir, Nanak).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): तुलसीदास को सगुण भक्ति कवियों में गिना जाता है। कारण (R): उन्होंने राम की उपासना रूप और गुणों वाले साकार ईश्वर के रूप में की।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है: सगुण भक्ति गुणयुक्त ईश्वर (राम, कृष्ण) की भक्ति है, जबकि निर्गुण भक्ति निराकार ईश्वर (कबीर, नानक) की।"},
  {"id":"history-bhakti-sufi-74","question":"Assertion (A): Nizamuddin Auliya's khanqah in Delhi drew people of every class and community. Reason (R): Nizamuddin Auliya held high office at the court of the Delhi Sultans.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true. R is false: like other Chishtis, Nizamuddin kept away from the court and refused royal service; his open kitchen and sama drew people from all walks of life.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): दिल्ली में निज़ामुद्दीन औलिया की खानकाह में हर वर्ग और समुदाय के लोग आते थे। कारण (R): निज़ामुद्दीन औलिया दिल्ली के सुल्तानों के दरबार में उच्च पद पर थे।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"A सही है। R गलत है: अन्य चिश्तियों की तरह निज़ामुद्दीन दरबार से दूर रहे और राजकीय सेवा अस्वीकार की; उनके खुले लंगर और समा में हर वर्ग के लोग आते थे।"},
  {"id":"history-bhakti-sufi-75","question":"Assertion (A): The Naqshbandi order insisted on strict observance of the sharia. Reason (R): Shaikh Ahmad Sirhindi belonged to the Naqshbandi order.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but R does not explain A. The order's orthodoxy predates Sirhindi; he was simply its most prominent Indian member in Akbar's and Jahangir's time.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): नक्शबंदी सिलसिला शरीअत के कठोर पालन पर बल देता था। कारण (R): शेख अहमद सरहिंदी नक्शबंदी सिलसिले के थे।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"दोनों सही हैं, लेकिन R, A की व्याख्या नहीं करता। सिलसिले की रूढ़िवादिता सरहिंदी से पहले की है; वे अकबर और जहाँगीर के समय इसके सबसे प्रमुख भारतीय सदस्य मात्र थे।"},
  {"id":"history-bhakti-sufi-76","question":"Which pair of saint and traditional occupation is NOT correctly matched?","options":["Kabir — weaver","Ravidas — leather worker","Namdev — tailor","Sena — weaver"],"answer":3,"explanation":"Sena, whose hymn is in the Guru Granth Sahib, was a barber. The other three pairs are the traditional accounts.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संत और उसके परंपरागत पेशे का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["कबीर — जुलाहा","रविदास — चर्मकार","नामदेव — दर्ज़ी","सेना — जुलाहा"],"explanationHi":"सेना, जिनका भजन गुरु ग्रंथ साहिब में है, नाई थे। शेष तीन युग्म परंपरागत वृत्तांतों के अनुसार हैं।"},
  {"id":"history-bhakti-sufi-77","question":"How many of the following were Nayanars (Shiva devotees)? Appar, Sundarar, Nammalvar, Periyalvar","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Appar and Sundarar were Nayanars (with Sambandar, the authors of the Tevaram). Nammalvar and Periyalvar (Andal's foster-father) were Alvars, devotees of Vishnu.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने नयनार (शिव भक्त) थे? अप्पर, सुंदरर, नम्मालवार, पेरियालवार","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"अप्पर और सुंदरर नयनार थे (संबंदर के साथ, तेवारम् के रचयिता)। नम्मालवार और पेरियालवार (आंडाल के पालक पिता) आलवार थे, जो विष्णु के भक्त थे।"},
  {"id":"history-bhakti-sufi-78","question":"Arrange these teachers in chronological order: 1. Ramanuja 2. Basavanna 3. Shankaracharya 4. Madhvacharya","options":["3-2-1-4","3-1-2-4","1-3-2-4","3-1-4-2"],"answer":1,"explanation":"Shankaracharya – 8th century; Ramanuja – 11th–12th century (traditionally 1017–1137); Basavanna – 12th century; Madhvacharya – 13th century (1238–1317).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन आचार्यों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. रामानुज 2. बसवण्णा 3. शंकराचार्य 4. मध्वाचार्य","optionsHi":["3-2-1-4","3-1-2-4","1-3-2-4","3-1-4-2"],"explanationHi":"शंकराचार्य – 8वीं शताब्दी; रामानुज – 11वीं-12वीं शताब्दी (परंपरागत रूप से 1017-1137); बसवण्णा – 12वीं शताब्दी; मध्वाचार्य – 13वीं शताब्दी (1238-1317)।"},
  {"id":"history-bhakti-sufi-79","question":"Arrange these saints in chronological order: 1. Tukaram 2. Basavanna 3. Ekanath 4. Jnaneshwar","options":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"answer":0,"explanation":"Basavanna – 12th century; Jnaneshwar – late 13th century; Ekanath – 16th century; Tukaram – 17th century, a contemporary of Shivaji.","difficulty":"very-hard","source":"SSC CGL · State PSCs","questionHi":"इन संतों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. तुकाराम 2. बसवण्णा 3. एकनाथ 4. ज्ञानेश्वर","optionsHi":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"explanationHi":"बसवण्णा – 12वीं शताब्दी; ज्ञानेश्वर – 13वीं शताब्दी का उत्तरार्ध; एकनाथ – 16वीं शताब्दी; तुकाराम – 17वीं शताब्दी, शिवाजी के समकालीन।"},
  {"id":"history-bhakti-sufi-80","question":"Which pair of Sikh Guru and contribution is NOT correctly matched?","options":["Guru Angad — Gurmukhi script","Guru Amar Das — manji system of preaching districts","Guru Arjan Dev — compilation of the Adi Granth","Guru Hargobind — founding of the Khalsa"],"answer":3,"explanation":"The Khalsa was founded by Guru Gobind Singh in 1699. Guru Hargobind's contributions were the Akal Takht and the doctrine of miri-piri.","difficulty":"very-hard","source":"SSC CGL · State PSCs","questionHi":"सिख गुरु और उसके योगदान का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["गुरु अंगद — गुरमुखी लिपि","गुरु अमर दास — मंजी प्रणाली (प्रचार क्षेत्र)","गुरु अर्जन देव — आदि ग्रंथ का संकलन","गुरु हरगोबिंद — खालसा की स्थापना"],"explanationHi":"खालसा की स्थापना गुरु गोविंद सिंह ने 1699 में की थी। गुरु हरगोबिंद के योगदान अकाल तख्त और मीरी-पीरी का सिद्धांत थे।"},
  {"id":"history-bhakti-sufi-81","question":"How many of these statements about the Lingayats (Virashaivas) are correct? I. They worship Shiva in the form of a linga. II. They traditionally bury their dead instead of cremating them. III. They encouraged child marriage. IV. They approved of the remarriage of widows.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. The Lingayats encouraged post-puberty marriage and widow remarriage, the opposite of the Dharmashastra norms of their time.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"लिंगायतों (वीरशैवों) के बारे में इनमें से कितने कथन सही हैं? I. वे शिव की पूजा लिंग रूप में करते हैं। II. वे परंपरागत रूप से अपने मृतकों का दाह-संस्कार करने के बजाय उन्हें दफनाते हैं। III. उन्होंने बाल विवाह को प्रोत्साहित किया। IV. उन्होंने विधवा पुनर्विवाह का समर्थन किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। लिंगायतों ने यौवन के बाद विवाह और विधवा पुनर्विवाह को प्रोत्साहित किया, जो उस समय के धर्मशास्त्र के नियमों के विपरीत था।"},
  {"id":"history-bhakti-sufi-82","question":"Assertion (A): Guru Gobind Singh compiled the Adi Granth in 1604. Reason (R): Guru Gobind Singh added the hymns of Guru Tegh Bahadur to the Granth.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: Guru Arjan Dev compiled the Adi Granth in 1604. R is true: Guru Gobind Singh added his father's hymns, producing the version known as the Damdami Bir.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): गुरु गोविंद सिंह ने 1604 में आदि ग्रंथ का संकलन किया। कारण (R): गुरु गोविंद सिंह ने ग्रंथ में गुरु तेग बहादुर के भजन जोड़े।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A सही है, लेकिन R गलत है","A गलत है, लेकिन R सही है"],"explanationHi":"A गलत है: आदि ग्रंथ का संकलन गुरु अर्जन देव ने 1604 में किया। R सही है: गुरु गोविंद सिंह ने अपने पिता के भजन जोड़े, जिससे दमदमी बीड़ के नाम से जाना जाने वाला संस्करण बना।"},
  {"id":"history-bhakti-sufi-83","question":"How many of these statements are correct? I. Surdas composed his verses in Braj bhasha. II. Tulsidas was a contemporary of Akbar. III. Jayasi wrote the Padmavat in Awadhi. IV. Raskhan, a Muslim poet, wrote devotional verse on Krishna.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Tulsidas (1532–1623) lived through Akbar's reign; Jayasi's Padmavat (1540) is in Awadhi; Raskhan's Krishna poetry is in Braj.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. सूरदास ने अपनी रचनाएँ ब्रज भाषा में कीं। II. तुलसीदास अकबर के समकालीन थे। III. जायसी ने पद्मावत अवधी में लिखा। IV. रसखान, एक मुस्लिम कवि, ने कृष्ण पर भक्ति काव्य लिखा।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। तुलसीदास (1532-1623) अकबर के पूरे शासनकाल में जीवित रहे; जायसी का पद्मावत (1540) अवधी में है; रसखान की कृष्ण-काव्य रचना ब्रज में है।"},
  {"id":"history-bhakti-sufi-84","question":"Match the Sufi term with its meaning: A. Wali B. Barakat C. Zikr D. Ziyarat — 1. Spiritual grace or power 2. Pilgrimage to a saint's tomb 3. A friend of God, a saint 4. Remembrance of God by repeating His names","options":["A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"answer":3,"explanation":"Wali – friend of God (plural auliya); barakat – grace believed to flow from the saint; zikr – repetition of God's names; ziyarat – visiting a dargah for blessings.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सूफी शब्द का उसके अर्थ से मिलान कीजिए: A. वली B. बरकत C. ज़िक्र D. ज़ियारत — 1. आध्यात्मिक कृपा या शक्ति 2. किसी संत के मकबरे की तीर्थयात्रा 3. ईश्वर का मित्र, संत 4. ईश्वर के नामों को दोहराकर उसका स्मरण","optionsHi":["A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"explanationHi":"वली – ईश्वर का मित्र (बहुवचन औलिया); बरकत – संत से प्रवाहित मानी जाने वाली कृपा; ज़िक्र – ईश्वर के नामों का दोहराव; ज़ियारत – आशीर्वाद के लिए दरगाह जाना।"},
  {"id":"history-bhakti-sufi-85","question":"Which one of the following saints did NOT belong to the Varkari tradition of Pandharpur?","options":["Tukaram","Jnaneshwar","Ekanath","Chaitanya"],"answer":3,"explanation":"Tukaram, Jnaneshwar and Ekanath were Varkari saints devoted to Vitthala (Vithoba) of Pandharpur. Chaitanya founded the Gaudiya Vaishnava tradition of Bengal.","difficulty":"very-hard","source":"SSC CGL · State PSCs","questionHi":"निम्नलिखित में से कौन-सा संत पंढरपुर की वारकरी परंपरा का नहीं था?","optionsHi":["तुकाराम","ज्ञानेश्वर","एकनाथ","चैतन्य"],"explanationHi":"तुकाराम, ज्ञानेश्वर और एकनाथ पंढरपुर के विट्ठल (विठोबा) के भक्त वारकरी संत थे। चैतन्य ने बंगाल की गौड़ीय वैष्णव परंपरा की स्थापना की।"},
  {"id":"history-bhakti-sufi-86","question":"Vidyapati composed his famous devotional and love songs (padavali) on Radha and Krishna in:","options":["Braj Bhasha","Awadhi","Maithili","Bhojpuri"],"answer":2,"explanation":"Vidyapati (14th–15th century) wrote in Maithili, and his songs deeply influenced Chaitanya's movement in Bengal. Surdas wrote in Braj and Tulsidas in Awadhi.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"विद्यापति ने राधा और कृष्ण पर अपने प्रसिद्ध भक्ति और प्रेम गीत (पदावली) किस भाषा में रचे?","optionsHi":["ब्रज भाषा","अवधी","मैथिली","भोजपुरी"],"explanationHi":"विद्यापति (14वीं-15वीं शताब्दी) ने मैथिली में लिखा, और उनके गीतों ने बंगाल में चैतन्य के आंदोलन को गहराई से प्रभावित किया। सूरदास ने ब्रज में और तुलसीदास ने अवधी में लिखा।"},
  {"id":"history-bhakti-sufi-87","question":"Which Sufi saint of Delhi is popularly called “Mehboob-e-Ilahi” (Beloved of God)?","options":["Nizamuddin Auliya","Moinuddin Chishti","Baba Farid","Shaikh Salim Chishti"],"answer":0,"explanation":"Nizamuddin Auliya (d. 1325), whose dargah is in Delhi, is called Mehboob-e-Ilahi. Moinuddin Chishti is known as Gharib Nawaz.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"दिल्ली के किस सूफी संत को लोकप्रिय रूप से 'महबूब-ए-इलाही' (ईश्वर का प्रिय) कहा जाता है?","optionsHi":["निज़ामुद्दीन औलिया","मोईनुद्दीन चिश्ती","बाबा फरीद","शेख सलीम चिश्ती"],"explanationHi":"निज़ामुद्दीन औलिया (मृत्यु 1325), जिनकी दरगाह दिल्ली में है, महबूब-ए-इलाही कहलाते हैं। मोईनुद्दीन चिश्ती ग़रीब नवाज़ के नाम से जाने जाते हैं।"},
  {"id":"history-bhakti-sufi-88","question":"The short prose-poems of Basavanna and other Virashaiva saints are called:","options":["Abhangas","Vachanas","Dohas","Pasurams"],"answer":1,"explanation":"Vachanas are Kannada sayings of the Lingayat saints. Abhangas are Marathi Varkari songs, dohas Hindi couplets and pasurams the Tamil hymns of the Alvars.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"बसवण्णा और अन्य वीरशैव संतों की छोटी गद्य-कविताएँ क्या कहलाती हैं?","optionsHi":["अभंग","वचन","दोहे","पासुरम्"],"explanationHi":"वचन लिंगायत संतों की कन्नड़ उक्तियाँ हैं। अभंग मराठी वारकरी गीत हैं, दोहे हिंदी के छंद हैं, और पासुरम् आलवारों के तमिल भजन हैं।"},
  {"id":"history-bhakti-sufi-89","question":"According to Sikh tradition, the foundation stone of the Harmandir Sahib at Amritsar was laid in Guru Arjan Dev's time by the Sufi saint:","options":["Baba Farid","Shaikh Ahmad Sirhindi","Bulleh Shah","Mian Mir"],"answer":3,"explanation":"Tradition holds that Mian Mir of Lahore, a Qadiri Sufi, laid the foundation stone in 1588 at Guru Arjan's invitation, symbolising openness to all.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"सिख परंपरा के अनुसार, अमृतसर के हरमंदिर साहिब की नींव का पत्थर गुरु अर्जन देव के समय में किस सूफी संत ने रखा?","optionsHi":["बाबा फरीद","शेख अहमद सरहिंदी","बुल्ले शाह","मियाँ मीर"],"explanationHi":"परंपरा के अनुसार लाहौर के कादिरी सूफी मियाँ मीर ने गुरु अर्जन के आमंत्रण पर 1588 में नींव का पत्थर रखा, जो सभी के लिए खुलेपन का प्रतीक है।"},
  {"id":"history-bhakti-sufi-90","question":"Vallabhacharya's philosophy, which underlies the Pushti Marga, is called:","options":["Vishishtadvaita","Shuddhadvaita","Dvaita","Achintya Bhedabheda"],"answer":1,"explanation":"Vallabha taught Shuddhadvaita (pure non-dualism). Vishishtadvaita is Ramanuja's, Dvaita Madhva's and Achintya Bhedabheda Chaitanya's.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"वल्लभाचार्य का दर्शन, जो पुष्टिमार्ग का आधार है, क्या कहलाता है?","optionsHi":["विशिष्टाद्वैत","शुद्धाद्वैत","द्वैत","अचिंत्य भेदाभेद"],"explanationHi":"वल्लभ ने शुद्धाद्वैत (शुद्ध अद्वैतवाद) का उपदेश दिया। विशिष्टाद्वैत रामानुज का, द्वैत मध्व का और अचिंत्य भेदाभेद चैतन्य का है।"},
  {"id":"history-bhakti-sufi-91","question":"The Borgeet, devotional songs still sung in Assam's sattras and namghars, were composed by:","options":["Sankaradeva and Madhavadeva","Chaitanya and Advaita Acharya","Jayadeva and Vidyapati","Lalan Fakir and Hason Raja"],"answer":0,"explanation":"Sankaradeva and his chief disciple Madhavadeva composed the Borgeet in Brajavali. Lalan Fakir was a 19th-century Baul of Bengal.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"असम के सत्रों और नामघरों में आज भी गाए जाने वाले भक्ति गीत बरगीत की रचना किसने की?","optionsHi":["शंकरदेव और माधवदेव","चैतन्य और अद्वैत आचार्य","जयदेव और विद्यापति","लालन फकीर और हसन राजा"],"explanationHi":"शंकरदेव और उनके प्रमुख शिष्य माधवदेव ने ब्रजावली में बरगीत की रचना की। लालन फकीर बंगाल के 19वीं शताब्दी के बाउल थे।"},
  {"id":"history-bhakti-sufi-92","question":"Kabir is traditionally believed to have died at:","options":["Varanasi","Prayag","Maghar","Ayodhya"],"answer":2,"explanation":"Kabir chose to die at Maghar, near Gorakhpur, to defy the belief that dying in Kashi brings salvation while dying at Maghar does not.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"परंपरा के अनुसार कबीर का देहांत कहाँ हुआ माना जाता है?","optionsHi":["वाराणसी","प्रयाग","मगहर","अयोध्या"],"explanationHi":"कबीर ने गोरखपुर के निकट मगहर में देह त्यागना चुना, इस मान्यता को चुनौती देने के लिए कि काशी में मरने से मोक्ष मिलता है और मगहर में नहीं।"},
  {"id":"history-bhakti-sufi-93","question":"The dargah of Khwaja Qutbuddin Bakhtiyar Kaki, successor of Moinuddin Chishti, is at:","options":["Ajmer, Rajasthan","Pakpattan, Punjab","Gulbarga, Deccan","Mehrauli, Delhi"],"answer":3,"explanation":"Bakhtiyar Kaki (d. 1235) lived in Delhi during Iltutmish's reign and is buried at Mehrauli. Baba Farid's shrine is at Pakpattan.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"मोईनुद्दीन चिश्ती के उत्तराधिकारी ख्वाजा क़ुतुबुद्दीन बख्तियार काकी की दरगाह कहाँ है?","optionsHi":["अजमेर, राजस्थान","पाकपट्टन, पंजाब","गुलबर्गा, दक्कन","महरौली, दिल्ली"],"explanationHi":"बख्तियार काकी (मृत्यु 1235) इल्तुतमिश के शासनकाल में दिल्ली में रहे और महरौली में दफन हैं। बाबा फरीद की दरगाह पाकपट्टन में है।"},
  {"id":"history-bhakti-sufi-94","question":"Which Sikh Guru became Guru at the age of about five, the youngest ever?","options":["Guru Har Rai","Guru Har Krishan","Guru Hargobind","Guru Gobind Singh"],"answer":1,"explanation":"Guru Har Krishan succeeded Guru Har Rai in 1661 as a child and died of smallpox in Delhi in 1664; Gurdwara Bangla Sahib is associated with him.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कौन-से सिख गुरु लगभग पाँच वर्ष की आयु में गुरु बने, जो अब तक सबसे कम आयु थी?","optionsHi":["गुरु हर राय","गुरु हर कृष्ण","गुरु हरगोबिंद","गुरु गोविंद सिंह"],"explanationHi":"गुरु हर कृष्ण 1661 में बालक रूप में गुरु हर राय के उत्तराधिकारी बने और 1664 में दिल्ली में चेचक से उनका देहांत हुआ; गुरुद्वारा बंगला साहिब उनसे जुड़ा है।"},
  {"id":"history-bhakti-sufi-95","question":"Shaikh Muhammad Ghaus of Gwalior, near whose tomb Tansen lies buried, belonged to which Sufi order?","options":["Chishti","Suhrawardi","Naqshbandi","Shattari"],"answer":3,"explanation":"Muhammad Ghaus was a leading Shattari saint, respected by Humayun. Tansen's tomb stands in the garden of his mausoleum at Gwalior.","difficulty":"hard","source":"UPSC Prelims","questionHi":"ग्वालियर के शेख मुहम्मद गौस, जिनके मकबरे के निकट तानसेन दफन हैं, किस सूफी सिलसिले के थे?","optionsHi":["चिश्ती","सुहरावर्दी","नक्शबंदी","शत्तारी"],"explanationHi":"मुहम्मद गौस शत्तारी सिलसिले के प्रमुख संत थे, जिनका हुमायूँ आदर करते थे। तानसेन का मकबरा ग्वालियर में उनके मकबरे के उद्यान में है।"},
  {"id":"history-bhakti-sufi-96","question":"The manji system, which divided the Sikh community into units for preaching and organisation, was introduced by:","options":["Guru Angad","Guru Amar Das","Guru Arjan Dev","Guru Hargobind"],"answer":1,"explanation":"Guru Amar Das set up 22 manjis and strengthened the langar at Goindwal. Guru Angad is credited with the Gurmukhi script.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मंजी प्रणाली, जिसने सिख समुदाय को प्रचार और संगठन के लिए इकाइयों में बाँटा, किसने आरंभ की?","optionsHi":["गुरु अंगद","गुरु अमर दास","गुरु अर्जन देव","गुरु हरगोबिंद"],"explanationHi":"गुरु अमर दास ने 22 मंजियाँ स्थापित कीं और गोइंदवाल में लंगर को सुदृढ़ किया। गुरु अंगद को गुरमुखी लिपि का श्रेय दिया जाता है।"},
  {"id":"history-bhakti-sufi-97","question":"The Dasam Granth is a collection of compositions attributed to:","options":["Guru Nanak","Guru Tegh Bahadur","Guru Gobind Singh","Guru Arjan Dev"],"answer":2,"explanation":"The Dasam Granth (“Book of the Tenth”) contains works attributed to Guru Gobind Singh, such as the Jaap Sahib. It is distinct from the Guru Granth Sahib.","difficulty":"hard","source":"UPSC Prelims","questionHi":"दशम ग्रंथ किसकी ओर आरोपित रचनाओं का संग्रह है?","optionsHi":["गुरु नानक","गुरु तेग बहादुर","गुरु गोविंद सिंह","गुरु अर्जन देव"],"explanationHi":"दशम ग्रंथ ('दसवें का ग्रंथ') में गुरु गोविंद सिंह को आरोपित रचनाएँ हैं, जैसे जाप साहिब। यह गुरु ग्रंथ साहिब से अलग है।"},
  {"id":"history-bhakti-sufi-98","question":"The Nath Panthi yogis, who influenced Kabir and other Nirguna saints, trace their tradition to Matsyendranath and:","options":["Gorakhnath","Namdev","Ramananda","Dadu Dayal"],"answer":0,"explanation":"The Naths, followers of Gorakhnath, rejected caste and ritual and practised hatha yoga; their vocabulary appears in Kabir's poetry.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कबीर और अन्य निर्गुण संतों को प्रभावित करने वाले नाथपंथी योगी अपनी परंपरा को मत्स्येंद्रनाथ और किससे जोड़ते हैं?","optionsHi":["गोरखनाथ","नामदेव","रामानंद","दादू दयाल"],"explanationHi":"गोरखनाथ के अनुयायी नाथों ने जाति और कर्मकांड को अस्वीकार किया और हठयोग का अभ्यास किया; उनकी शब्दावली कबीर की कविता में दिखती है।"},
  {"id":"history-bhakti-sufi-99","question":"Janabai, a woman saint of the Varkari tradition whose abhangas are still sung, lived as a servant in the household of:","options":["Tukaram","Namdev","Eknath","Jnaneshwar"],"answer":1,"explanation":"Janabai was a maid in Namdev's family at Pandharpur and became one of the best-known women Varkari poets.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वारकरी परंपरा की महिला संत जनाबाई, जिनके अभंग आज भी गाए जाते हैं, किसके घर में सेविका के रूप में रहती थीं?","optionsHi":["तुकाराम","नामदेव","एकनाथ","ज्ञानेश्वर"],"explanationHi":"जनाबाई पंढरपुर में नामदेव के परिवार की दासी थीं और सबसे प्रसिद्ध महिला वारकरी कवयित्रियों में से एक बनीं।"},
  {"id":"history-bhakti-sufi-100","question":"Kanakadasa, a Haridasa saint of Karnataka from the shepherd (Kuruba) community, is linked by legend to a window at the Krishna temple in:","options":["Udupi","Hampi","Sringeri","Melukote"],"answer":0,"explanation":"The “Kanakana Kindi” at Udupi marks the spot where, by legend, the idol turned to give darshan to Kanakadasa, who was denied entry.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कर्नाटक के हरिदास संत कनकदास, जो चरवाहा (कुरुबा) समुदाय के थे, किंवदंती के अनुसार किस स्थान के कृष्ण मंदिर की एक खिड़की से जुड़े हैं?","optionsHi":["उडुपी","हम्पी","शृंगेरी","मेलुकोटे"],"explanationHi":"उडुपी की 'कनकन किंडी' वह स्थान है जहाँ किंवदंती के अनुसार प्रवेश से वंचित कनकदास को दर्शन देने के लिए मूर्ति घूम गई।"},
  {"id":"history-bhakti-sufi-101","question":"Which Chishti saint, successor of Nizamuddin Auliya, was called “Chirag-i-Dehli” (Lamp of Delhi)?","options":["Amir Khusrau","Khwaja Bande Nawaz Gesudaraz","Shaikh Nasiruddin Mahmud","Shaikh Salim Chishti"],"answer":2,"explanation":"Nasiruddin Mahmud (d. 1356) led the Chishtis in Delhi after Nizamuddin. His disciple Gesudaraz took the order to Gulbarga in the Deccan.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निज़ामुद्दीन औलिया के उत्तराधिकारी किस चिश्ती संत को 'चिराग-ए-दिल्ली' (दिल्ली का दीपक) कहा गया?","optionsHi":["अमीर खुसरो","ख्वाजा बंदा नवाज़ गेसूदराज़","शेख नसीरुद्दीन महमूद","शेख सलीम चिश्ती"],"explanationHi":"नसीरुद्दीन महमूद (मृत्यु 1356) ने निज़ामुद्दीन के बाद दिल्ली में चिश्तियों का नेतृत्व किया। उनके शिष्य गेसूदराज़ इस सिलसिले को दक्कन के गुलबर्गा ले गए।"},
  {"id":"history-bhakti-sufi-102","question":"According to tradition, Tansen learned music from the saint-musician Swami Haridas, who lived at:","options":["Pandharpur","Puri","Vrindavan","Ayodhya"],"answer":2,"explanation":"Swami Haridas, a Krishna devotee and dhrupad master, lived at Vrindavan. Legend says Akbar went in disguise with Tansen to hear him.","difficulty":"hard","source":"UPSC Prelims","questionHi":"परंपरा के अनुसार तानसेन ने संत-संगीतज्ञ स्वामी हरिदास से संगीत सीखा, जो कहाँ रहते थे?","optionsHi":["पंढरपुर","पुरी","वृंदावन","अयोध्या"],"explanationHi":"कृष्ण भक्त और ध्रुपद के गुरु स्वामी हरिदास वृंदावन में रहते थे। किंवदंती है कि अकबर भेष बदलकर तानसेन के साथ उन्हें सुनने गए थे।"},
  {"id":"history-bhakti-sufi-103","question":"Dhanna, whose hymns appear in the Guru Granth Sahib, was a Bhakti saint from a family of:","options":["Muslim weavers in Varanasi","Jat peasants in Rajasthan","Tailors in Maharashtra","Barbers in Punjab"],"answer":1,"explanation":"Dhanna was a Jat farmer from Rajasthan, traditionally a disciple of Ramananda. Kabir was a weaver, Namdev a tailor and Sena a barber.","difficulty":"hard","source":"UPSC Prelims","questionHi":"धन्ना, जिनके भजन गुरु ग्रंथ साहिब में हैं, किस परिवार के भक्त संत थे?","optionsHi":["वाराणसी के मुस्लिम जुलाहे","राजस्थान के जाट किसान","महाराष्ट्र के दर्ज़ी","पंजाब के नाई"],"explanationHi":"धन्ना राजस्थान के जाट किसान थे, और परंपरा के अनुसार रामानंद के शिष्य। कबीर जुलाहे थे, नामदेव दर्ज़ी और सेना नाई।"},
  {"id":"history-bhakti-sufi-104","question":"Munis-ul-Arwah, a biography of Khwaja Moinuddin Chishti, was written by the Mughal princess:","options":["Gulbadan Begum","Jahanara Begum","Zeb-un-Nisa","Roshanara Begum"],"answer":1,"explanation":"Jahanara, Shah Jahan's daughter and a Qadiri disciple, wrote Munis-ul-Arwah. Gulbadan wrote the Humayun-nama; Zeb-un-Nisa was a poet.","difficulty":"hard","source":"UPSC Prelims","questionHi":"ख्वाजा मोईनुद्दीन चिश्ती की जीवनी 'मुनीस-उल-अरवाह' किस मुगल राजकुमारी ने लिखी?","optionsHi":["गुलबदन बेगम","जहाँआरा बेगम","ज़ेब-उन-निसा","रोशनआरा बेगम"],"explanationHi":"शाहजहाँ की पुत्री और कादिरी शिष्या जहाँआरा ने मुनीस-उल-अरवाह लिखी। गुलबदन ने हुमायूँनामा लिखा; ज़ेब-उन-निसा कवयित्री थीं।"},
  {"id":"history-bhakti-sufi-105","question":"Match the Telugu saint-poet with the contribution: A. Annamacharya B. Bammera Potana C. Bhadrachala Ramadasu D. Tyagaraja — 1. Telugu rendering of the Bhagavata Purana 2. Thousands of kirtanas to Venkateswara of Tirupati 3. Built the Rama temple at Bhadrachalam 4. The Pancharatna kritis","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Annamacharya sang of Venkateswara, Potana wrote the Andhra Maha Bhagavatamu, Ramadasu (Kancherla Gopanna) built the Bhadrachalam temple, and Tyagaraja composed the Pancharatna kritis.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"तेलुगु संत-कवि का उसके योगदान से मिलान कीजिए: A. अन्नमाचार्य B. बम्मेरा पोतना C. भद्राचल रामदासु D. त्यागराज — 1. भागवत पुराण का तेलुगु रूपांतरण 2. तिरुपति के वेंकटेश्वर को समर्पित हज़ारों कीर्तन 3. भद्राचलम में राम मंदिर का निर्माण 4. पंचरत्न कृतियाँ","optionsHi":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3"],"explanationHi":"अन्नमाचार्य ने वेंकटेश्वर का गुणगान किया, पोतना ने आंध्र महाभागवतम् लिखा, रामदासु (कंचर्ला गोपन्ना) ने भद्राचलम मंदिर बनवाया, और त्यागराज ने पंचरत्न कृतियाँ रचीं।"},
  {"id":"history-bhakti-sufi-106","question":"Match the Sufi or mystic poet with the work or form: A. Waris Shah B. Lal Ded C. Bulleh Shah D. Shah Abdul Latif Bhittai — 1. Kafis in Punjabi 2. Shah Jo Risalo in Sindhi 3. Heer, a Punjabi verse romance 4. Vakhs in Kashmiri","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Waris Shah wrote Heer, Lal Ded spoke vakhs, Bulleh Shah of Kasur sang kafis, and Shah Abdul Latif's verse is collected in Shah Jo Risalo.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सूफी या रहस्यवादी कवि का उसकी रचना या विधा से मिलान कीजिए: A. वारिस शाह B. लल्ल द्यद C. बुल्ले शाह D. शाह अब्दुल लतीफ भिटाई — 1. पंजाबी में काफ़ियाँ 2. सिंधी में शाह जो रिसालो 3. हीर, एक पंजाबी काव्य-प्रेमाख्यान 4. कश्मीरी में वाख","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"वारिस शाह ने हीर लिखी, लल्ल द्यद ने वाख कहे, कसूर के बुल्ले शाह ने काफ़ियाँ गाईं, और शाह अब्दुल लतीफ की कविता शाह जो रिसालो में संकलित है।"},
  {"id":"history-bhakti-sufi-107","question":"Consider the following statements: 1. Jagannath Dasa rendered the Bhagavata Purana into Odia. 2. Sankaradeva rendered parts of the Bhagavata Purana into Assamese. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Regional Bhagavatas, like Potana's in Telugu and Ekanath's in Marathi, carried Krishna bhakti in people's languages.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. जगन्नाथ दास ने भागवत पुराण का ओड़िया में रूपांतरण किया। 2. शंकरदेव ने भागवत पुराण के कुछ अंशों का असमिया में रूपांतरण किया। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। क्षेत्रीय भागवतों, जैसे तेलुगु में पोतना का और मराठी में एकनाथ का, ने कृष्ण भक्ति को लोगों की भाषाओं में पहुँचाया।"},
  {"id":"history-bhakti-sufi-108","question":"Arrange these Chishti saints in the order of spiritual succession: 1. Nizamuddin Auliya 2. Baba Farid 3. Nasiruddin Chirag-i-Dehli 4. Qutbuddin Bakhtiyar Kaki","options":["2, 4, 1, 3","4, 1, 2, 3","4, 2, 3, 1","4, 2, 1, 3"],"answer":3,"explanation":"Moinuddin Chishti was followed by Bakhtiyar Kaki, then Baba Farid of Pakpattan, then Nizamuddin Auliya, then Nasiruddin Chirag-i-Dehli.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन चिश्ती संतों को आध्यात्मिक उत्तराधिकार के क्रम में व्यवस्थित कीजिए: 1. निज़ामुद्दीन औलिया 2. बाबा फरीद 3. नसीरुद्दीन चिराग-ए-दिल्ली 4. क़ुतुबुद्दीन बख्तियार काकी","optionsHi":["2, 4, 1, 3","4, 1, 2, 3","4, 2, 3, 1","4, 2, 1, 3"],"explanationHi":"मोईनुद्दीन चिश्ती के बाद बख्तियार काकी, फिर पाकपट्टन के बाबा फरीद, फिर निज़ामुद्दीन औलिया, फिर नसीरुद्दीन चिराग-ए-दिल्ली हुए।"},
  {"id":"history-bhakti-sufi-109","question":"Assertion (A): Kabir rejected both idol worship and ritual prayer. Reason (R): Kabir was a Nirguna bhakta who saw God as formless and present within every being.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: since God has no form and dwells within, Kabir saw no need for images, pilgrimages or set rituals of either faith.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कबीर ने मूर्ति पूजा और कर्मकांडी प्रार्थना दोनों को अस्वीकार किया। कारण (R): कबीर निर्गुण भक्त थे जो ईश्वर को निराकार और प्रत्येक प्राणी में विद्यमान मानते थे।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं पर R, A की सही व्याख्या नहीं है","A सही है पर R गलत है","A गलत है पर R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है: ईश्वर निराकार है और भीतर निवास करता है, इसलिए कबीर को दोनों धर्मों की मूर्तियों, तीर्थयात्राओं या निर्धारित कर्मकांडों की आवश्यकता नहीं दिखी।"},
  {"id":"history-bhakti-sufi-110","question":"How many of these statements about Sankaradeva are correct? I. He founded the Ekasarana Dharma. II. He created the one-act Ankiya Naat plays. III. He set up namghars as village prayer halls. IV. He was a contemporary of Chaitanya Mahaprabhu.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Sankaradeva (1449–1568) outlived Chaitanya (1486–1534), and his Ankiya Naat performances are known as Bhaona.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"शंकरदेव के बारे में इनमें से कितने कथन सही हैं? I. उन्होंने एकशरण धर्म की स्थापना की। II. उन्होंने एकांकी अंकिया नाट की रचना की। III. उन्होंने गाँवों में प्रार्थना-गृह के रूप में नामघर स्थापित किए। IV. वे चैतन्य महाप्रभु के समकालीन थे।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। शंकरदेव (1449-1568) चैतन्य (1486-1534) के बाद भी जीवित रहे, और उनके अंकिया नाट के प्रदर्शन भाओना कहलाते हैं।"},
  {"id":"history-bhakti-sufi-111","question":"Consider the following statements: 1. Mian Mir of Lahore belonged to the Qadiri order. 2. Dara Shikoh followed the Qadiri order as a disciple of Mulla Shah Badakhshi, Mian Mir's successor. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. The Qadiri order, named after Abdul Qadir Jilani of Baghdad, won the devotion of Dara Shikoh and Jahanara.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. लाहौर के मियाँ मीर कादिरी सिलसिले के थे। 2. दारा शिकोह ने मियाँ मीर के उत्तराधिकारी मुल्ला शाह बदख्शी के शिष्य के रूप में कादिरी सिलसिले का अनुसरण किया। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। बगदाद के अब्दुल क़ादिर जीलानी के नाम पर बना कादिरी सिलसिला दारा शिकोह और जहाँआरा की श्रद्धा का पात्र बना।"},
  {"id":"history-bhakti-sufi-112","question":"Consider the following statements: 1. The Qalandars and Madaris were “be-sharia” Sufis who did not bind themselves to the sharia. 2. The Chishti and Suhrawardi orders were “ba-sharia” orders. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Ba-sharia orders accepted Islamic law; wandering be-sharia groups such as the Qalandars often ignored ritual rules.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. कलंदर और मदारी 'बे-शरा' सूफी थे जो शरीअत से बँधे नहीं थे। 2. चिश्ती और सुहरावर्दी सिलसिले 'बा-शरा' सिलसिले थे। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। बा-शरा सिलसिले इस्लामी कानून को मानते थे; कलंदर जैसे घुमक्कड़ बे-शरा समूह प्रायः कर्मकांडीय नियमों की उपेक्षा करते थे।"},
  {"id":"history-bhakti-sufi-113","question":"Arrange these saints in chronological order: 1. Tukaram 2. Andal 3. Sankaradeva 4. Basavanna","options":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","2, 4, 1, 3"],"answer":0,"explanation":"Andal (8th century), Basavanna (12th century), Sankaradeva (15th–16th century) and Tukaram (17th century).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन संतों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. तुकाराम 2. आंडाल 3. शंकरदेव 4. बसवण्णा","optionsHi":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","2, 4, 1, 3"],"explanationHi":"आंडाल (8वीं शताब्दी), बसवण्णा (12वीं शताब्दी), शंकरदेव (15वीं-16वीं शताब्दी) और तुकाराम (17वीं शताब्दी)।"},
  {"id":"history-bhakti-sufi-114","question":"Assertion (A): Chokhamela's abhangas voice the pain of being kept outside the Vitthala temple at Pandharpur. Reason (R): Chokhamela belonged to the Mahar community, then treated as untouchable.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Chokhamela (14th century), a Varkari saint, was denied temple entry because of caste; his samadhi stands at the temple steps.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): चोखामेळा के अभंग पंढरपुर के विट्ठल मंदिर से बाहर रखे जाने की पीड़ा व्यक्त करते हैं। कारण (R): चोखामेळा महार समुदाय के थे, जिसे उस समय अस्पृश्य माना जाता था।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं पर R, A की सही व्याख्या नहीं है","A सही है पर R गलत है","A गलत है पर R सही है"],"explanationHi":"दोनों सही हैं और R, A की व्याख्या करता है। वारकरी संत चोखामेळा (14वीं शताब्दी) को जाति के कारण मंदिर प्रवेश से वंचित किया गया; उनकी समाधि मंदिर की सीढ़ियों पर है।"},
  {"id":"history-bhakti-sufi-115","question":"Match the teacher with the centre associated with him: A. Madhvacharya B. Ramanuja C. Shankaracharya D. Vallabhacharya — 1. Nathdwara (Shrinathji) 2. Udupi 3. Srirangam 4. Sringeri","options":["A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"answer":2,"explanation":"Madhva founded the Krishna temple tradition at Udupi, Ramanuja led the Srirangam temple, Shankara set up a matha at Sringeri, and the Pushti Marga's chief shrine of Shrinathji is at Nathdwara.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आचार्य का उससे संबद्ध केंद्र से मिलान कीजिए: A. मध्वाचार्य B. रामानुज C. शंकराचार्य D. वल्लभाचार्य — 1. नाथद्वारा (श्रीनाथजी) 2. उडुपी 3. श्रीरंगम 4. शृंगेरी","optionsHi":["A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1"],"explanationHi":"मध्व ने उडुपी में कृष्ण मंदिर परंपरा स्थापित की, रामानुज ने श्रीरंगम मंदिर का संचालन किया, शंकर ने शृंगेरी में मठ स्थापित किया, और पुष्टिमार्ग का प्रमुख श्रीनाथजी मंदिर नाथद्वारा में है।"},
  {"id":"history-bhakti-sufi-116","question":"Shaikh Ahmad Sirhindi rejected the doctrine of Wahdat-ul-Wujud ('unity of being'), associated with Ibn Arabi, and put forward in its place the doctrine of:","options":["Sulh-i-kul","Din-i-Ilahi","Wahdat-ul-Shuhud","Fana fi'l-Shaikh"],"answer":2,"explanation":"Sirhindi's Wahdat-ul-Shuhud ('unity of witness/appearance') held that the mystic's sense of oneness with God is subjective, keeping God and creation distinct and so restoring the primacy of the sharia. Sulh-i-kul and Din-i-Ilahi were Akbar's ideas, which he opposed.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"शेख अहमद सरहिंदी ने इब्न अरबी से जुड़े 'वहदत-उल-वुजूद' ('अस्तित्व की एकता') के सिद्धांत को अस्वीकार कर उसके स्थान पर किस सिद्धांत को प्रस्तुत किया?","optionsHi":["सुलह-ए-कुल","दीन-ए-इलाही","वहदत-उश-शुहूद","फना फ़िश-शैख़"],"explanationHi":"सरहिंदी के वहदत-उश-शुहूद ('प्रेक्षण/प्रतीति की एकता') के अनुसार ईश्वर से एकत्व की रहस्यवादी की अनुभूति व्यक्तिपरक है; ईश्वर और सृष्टि अलग रहते हैं और इस प्रकार शरीअत की प्रधानता पुनः स्थापित होती है। सुलह-ए-कुल और दीन-ए-इलाही अकबर के विचार थे, जिनका उन्होंने विरोध किया।"},
  {"id":"history-bhakti-sufi-117","question":"Consider the following statements about the Bauls: I. They are wandering minstrels of Bengal. II. Their songs blend Vaishnava Sahajiya and Sufi ideas and reject caste and ritual. III. Lalon Fakir is the most celebrated of the Baul poets. IV. Baul songs are composed in classical Sanskrit. Which of the statements given above are correct?","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Bauls sing in the everyday Bengali of the countryside, seeking the 'man of the heart' within, so IV is wrong. UNESCO proclaimed Baul songs (from Bangladesh) a Masterpiece of the Oral and Intangible Heritage of Humanity in 2005 and inscribed them on the Representative List in 2008.","difficulty":"hard","source":"UPSC Prelims","questionHi":"बाउलों के बारे में निम्नलिखित कथनों पर विचार कीजिए: I. वे बंगाल के घुमक्कड़ गायक हैं। II. उनके गीतों में वैष्णव सहजिया और सूफी विचारों का मिश्रण है और वे जाति और कर्मकांड को अस्वीकार करते हैं। III. लालन फकीर बाउल कवियों में सबसे प्रसिद्ध हैं। IV. बाउल गीत शास्त्रीय संस्कृत में रचे जाते हैं। ऊपर दिए गए कथनों में से कौन-से सही हैं?","optionsHi":["केवल I और II","केवल I, II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"बाउल ग्रामीण अंचल की रोज़मर्रा की बंगाली में गाते हैं और अपने भीतर 'हृदय के मानुष' को खोजते हैं, इसलिए IV गलत है। यूनेस्को ने (बांग्लादेश की) बाउल गीत परंपरा को 2005 में मानवता की मौखिक और अमूर्त विरासत की उत्कृष्ट कृति घोषित किया और 2008 में इसे प्रतिनिधि सूची में अंकित किया।"},
  {"id":"history-bhakti-sufi-118","question":"Of Adi Shankara's four mathas, the Sringeri Sharada Peetham, the seat of the south, stands in:","options":["Gujarat","Odisha","Karnataka","Uttarakhand"],"answer":2,"explanation":"Shankara's four mathas are at Sringeri (south, Karnataka), Dwarka (west, Gujarat), Puri (east, Odisha) and Jyotirmath (north, Uttarakhand). The other three states hold the other mathas.","difficulty":"moderate","questionHi":"आदि शंकर के चार मठों में दक्षिण का पीठ, शृंगेरी शारदा पीठम्, कहाँ स्थित है?","optionsHi":["गुजरात","ओडिशा","कर्नाटक","उत्तराखंड"],"explanationHi":"शंकर के चार मठ शृंगेरी (दक्षिण, कर्नाटक), द्वारका (पश्चिम, गुजरात), पुरी (पूर्व, ओडिशा) और ज्योतिर्मठ (उत्तर, उत्तराखंड) में हैं। अन्य तीन राज्यों में अन्य मठ हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"history-bhakti-sufi-119","question":"Basavanna served as a minister (bhandari) at the court of the Kalachuri king:","options":["Vikramaditya VI","Bijjala","Vishnuvardhana","Ballala II"],"answer":1,"explanation":"Basavanna rose to be a minister of the Kalachuri king Bijjala at Kalyana and used his position to build the Virashaiva community. The other kings belonged to the Chalukya and Hoysala dynasties.","difficulty":"hard","questionHi":"बसवण्णा किस कलचुरि राजा के दरबार में मंत्री (भंडारी) रहे?","optionsHi":["विक्रमादित्य षष्ठ","बिज्जल","विष्णुवर्धन","बल्लाल द्वितीय"],"explanationHi":"बसवण्णा कल्याण में कलचुरि राजा बिज्जल के मंत्री बने और उन्होंने इस पद का उपयोग वीरशैव समुदाय के निर्माण में किया। अन्य राजा चालुक्य और होयसल वंश के थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-120","question":"In the annual Varkari pilgrimage to Pandharpur, Tukaram's palkhi starts from Dehu, while Jnaneshwar's palkhi starts from:","options":["Alandi","Paithan","Jejuri","Nashik"],"answer":0,"explanation":"Jnaneshwar's palkhi leaves Alandi, where his samadhi stands, and joins Tukaram's from Dehu on the way to Pandharpur for Ashadhi Ekadashi. Paithan is the starting point of Eknath's palkhi.","difficulty":"hard","questionHi":"पंढरपुर की वार्षिक वारकरी यात्रा में तुकाराम की पालकी देहू से चलती है, जबकि ज्ञानेश्वर की पालकी कहाँ से चलती है?","optionsHi":["आलंदी","पैठण","जेजुरी","नासिक"],"explanationHi":"ज्ञानेश्वर की पालकी आलंदी से चलती है, जहाँ उनकी समाधि है, और आषाढ़ी एकादशी के लिए पंढरपुर जाते हुए देहू की तुकाराम की पालकी से मिल जाती है। पैठण एकनाथ की पालकी का प्रस्थान-स्थल है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-121","question":"Muktabai, a woman saint-poet of the Varkari tradition, was the sister of:","options":["Namdev, the Varkari tailor-saint","Tukaram, the saint-poet of Dehu","Eknath, the Brahmin saint of Paithan","Jnaneshwar, the saint of Alandi"],"answer":3,"explanation":"Muktabai was the younger sister of Jnaneshwar and the brothers Nivruttinath and Sopan, and she is remembered for her abhangas. She is not related to Namdev, Tukaram or Eknath.","difficulty":"hard","questionHi":"वारकरी परंपरा की संत-कवयित्री मुक्ताबाई किसकी बहन थीं?","optionsHi":["नामदेव, वारकरी दर्जी-संत","तुकाराम, देहू के संत-कवि","एकनाथ, पैठण के ब्राह्मण संत","ज्ञानेश्वर, आलंदी के संत"],"explanationHi":"मुक्ताबाई ज्ञानेश्वर और भाइयों निवृत्तिनाथ तथा सोपान की छोटी बहन थीं और अपने अभंगों के लिए याद की जाती हैं। उनका नामदेव, तुकाराम या एकनाथ से कोई संबंध नहीं था।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-122","question":"Bahinabai, a woman saint-poet of 17th-century Maharashtra, regarded herself as a follower of:","options":["Tukaram","Eknath","Ramdas","Jnaneshwar"],"answer":0,"explanation":"Bahinabai Pathak of the Kolhapur region became a devotee and disciple of Tukaram, and her autobiographical abhangas describe her struggle between family duty and devotion. Jnaneshwar and Eknath lived in earlier centuries.","difficulty":"very-hard","questionHi":"17वीं शताब्दी के महाराष्ट्र की संत-कवयित्री बहिणाबाई स्वयं को किसकी अनुयायी मानती थीं?","optionsHi":["तुकाराम","एकनाथ","रामदास","ज्ञानेश्वर"],"explanationHi":"कोल्हापुर क्षेत्र की बहिणाबाई पाठक तुकाराम की भक्त और शिष्या बनीं और उनके आत्मकथात्मक अभंग पारिवारिक कर्तव्य और भक्ति के बीच उनके संघर्ष का वर्णन करते हैं। ज्ञानेश्वर और एकनाथ पहले की शताब्दियों के थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-123","question":"The Mahanubhava sect of Maharashtra, whose early biographical prose work is the Lilacharitra, was founded in the 13th century by:","options":["Namdev","Ramdas","Chakradhara","Jnaneshwar"],"answer":2,"explanation":"Chakradhara Swami founded the Mahanubhava sect, which rejected caste and Vedic ritual and used Marathi for its teaching. Its Lilacharitra, by Mhaimbhat, is among the earliest Marathi prose works.","difficulty":"very-hard","questionHi":"महाराष्ट्र के महानुभाव पंथ, जिसकी आरंभिक जीवनीपरक गद्य रचना लीळाचरित्र है, की स्थापना 13वीं शताब्दी में किसने की?","optionsHi":["नामदेव","रामदास","चक्रधर","ज्ञानेश्वर"],"explanationHi":"चक्रधर स्वामी ने महानुभाव पंथ की स्थापना की, जिसने जाति और वैदिक कर्मकांड को अस्वीकार किया और शिक्षा के लिए मराठी का प्रयोग किया। म्हाइंभट का लीळाचरित्र मराठी की सबसे आरंभिक गद्य रचनाओं में है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-124","question":"Of all the writings attributed to Chaitanya Mahaprabhu, only eight Sanskrit verses are generally accepted as his own. They are known as:","options":["Prema-bhakti-chandrika","Shikshashtakam","Krishna-karnamrita","Chaitanya Bhagavata"],"answer":1,"explanation":"The Shikshashtakam, eight verses on devotion, humility and the chanting of the divine name, is the only work attributed to Chaitanya himself. The Chaitanya Bhagavata is a biography by Vrindavana Dasa.","difficulty":"very-hard","questionHi":"चैतन्य महाप्रभु के नाम से जुड़ी रचनाओं में केवल आठ संस्कृत श्लोक ही सामान्यतः उनके अपने माने जाते हैं। वे किस नाम से जाने जाते हैं?","optionsHi":["प्रेमभक्तिचंद्रिका","शिक्षाष्टकम्","कृष्णकर्णामृत","चैतन्य भागवत"],"explanationHi":"भक्ति, विनम्रता और नाम-जप पर आठ श्लोकों का शिक्षाष्टकम् ही चैतन्य की अपनी रचना माना जाता है। चैतन्य भागवत वृंदावन दास द्वारा लिखी जीवनी है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-125","question":"Match the work with its author: A. Chaitanya Charitamrita B. Chaitanya Bhagavata C. Chaitanya Mangala D. Sri Krishna Chaitanya Charitamritam (Sanskrit). Authors: 1. Murari Gupta 2. Krishnadasa Kaviraja 3. Vrindavana Dasa 4. Jayananda","options":["A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"Krishnadasa Kaviraja wrote the Chaitanya Charitamrita, Vrindavana Dasa the Chaitanya Bhagavata, Jayananda the Chaitanya Mangala, and Murari Gupta the earliest Sanskrit biography.","difficulty":"very-hard","questionHi":"रचना का उसके लेखक से मिलान कीजिए: A. चैतन्य चरितामृत B. चैतन्य भागवत C. चैतन्य मंगल D. श्रीकृष्ण चैतन्य चरितामृतम् (संस्कृत)। लेखक: 1. मुरारि गुप्त 2. कृष्णदास कविराज 3. वृंदावन दास 4. जयानंद","optionsHi":["A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"explanationHi":"कृष्णदास कविराज ने चैतन्य चरितामृत, वृंदावन दास ने चैतन्य भागवत, जयानंद ने चैतन्य मंगल और मुरारि गुप्त ने सबसे आरंभिक संस्कृत जीवनी लिखी।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-126","question":"Which of these was NOT one of the six Goswamis of Vrindavan associated with Chaitanya's Gaudiya Vaishnavism?","options":["Narottama Dasa","Rupa Goswami","Jiva Goswami","Gopala Bhatta"],"answer":0,"explanation":"The six Goswamis were Rupa, Sanatana, Gopala Bhatta, Raghunatha Bhatta, Raghunatha Dasa and Jiva. Narottama Dasa was a later Bengali Vaishnava who spread their teaching.","difficulty":"very-hard","questionHi":"चैतन्य के गौड़ीय वैष्णव मत से जुड़े वृंदावन के छह गोस्वामियों में इनमें से कौन शामिल नहीं था?","optionsHi":["नरोत्तम दास","रूप गोस्वामी","जीव गोस्वामी","गोपाल भट्ट"],"explanationHi":"छह गोस्वामी रूप, सनातन, गोपाल भट्ट, रघुनाथ भट्ट, रघुनाथ दास और जीव थे। नरोत्तम दास बाद के बंगाली वैष्णव थे जिन्होंने उनकी शिक्षाओं का प्रसार किया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-127","question":"Chaitanya Mahaprabhu was initiated into the Krishna mantra at Gaya by:","options":["Madhavendra Puri","Advaita Acharya","Ishvara Puri","Nityananda"],"answer":2,"explanation":"At Gaya in about 1508 Chaitanya was initiated by Ishvara Puri, a disciple of Madhavendra Puri, and returned to Nadia a changed man. Advaita and Nityananda became his close associates.","difficulty":"hard","questionHi":"गया में चैतन्य महाप्रभु को कृष्ण मंत्र की दीक्षा किसने दी?","optionsHi":["माधवेंद्र पुरी","अद्वैत आचार्य","ईश्वर पुरी","नित्यानंद"],"explanationHi":"लगभग 1508 में गया में चैतन्य को माधवेंद्र पुरी के शिष्य ईश्वर पुरी ने दीक्षा दी और वे बदले हुए व्यक्ति के रूप में नदिया लौटे। अद्वैत और नित्यानंद उनके निकट सहयोगी बने।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-128","question":"Namghosha, the Assamese devotional text recited in the namghars, was composed by Sankaradeva's chief disciple:","options":["Damodaradeva","Madhavadeva","Ananta Kandali","Harideva"],"answer":1,"explanation":"Madhavadeva composed the Namghosha, also called Hazari Ghosha, and consolidated the Ekasarana movement after Sankaradeva. Ananta Kandali translated parts of the Ramayana and Bhagavata into Assamese.","difficulty":"hard","questionHi":"नामघोषा, असम का भक्ति ग्रंथ जो नामघरों में पढ़ा जाता है, शंकरदेव के किस प्रमुख शिष्य ने रचा?","optionsHi":["दामोदरदेव","माधवदेव","अनंत कंदली","हरिदेव"],"explanationHi":"माधवदेव ने नामघोषा, जिसे हाजरी घोषा भी कहते हैं, रचा और शंकरदेव के बाद एकशरण आंदोलन को संगठित किया। अनंत कंदली ने रामायण और भागवत के अंशों का असमिया में अनुवाद किया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-129","question":"Qawwali, the devotional music of the Sufi gatherings, is traditionally said to have been developed by:","options":["Moinuddin Chishti","Baba Farid","Nizamuddin Auliya","Amir Khusrau"],"answer":3,"explanation":"Amir Khusrau, a disciple of Nizamuddin Auliya, is traditionally credited with blending Persian, Arabic and Indian elements into qawwali. The saints themselves approved of sama but did not create the form.","difficulty":"moderate","questionHi":"सूफी महफ़िलों का भक्ति संगीत, कव्वाली, परंपरागत रूप से किसके द्वारा विकसित माना जाता है?","optionsHi":["मोइनुद्दीन चिश्ती","बाबा फरीद","निज़ामुद्दीन औलिया","अमीर खुसरो"],"explanationHi":"निज़ामुद्दीन औलिया के शिष्य अमीर खुसरो को परंपरा से फारसी, अरबी और भारतीय तत्वों को मिलाकर कव्वाली बनाने का श्रेय दिया जाता है। संत स्वयं समा का समर्थन करते थे, पर उन्होंने यह शैली नहीं रची।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-130","question":"Dharamdas, a wealthy disciple of Kabir, is regarded as the founder of the branch of the Kabir Panth in:","options":["Chhattisgarh region","Bengal and Odisha","Gujarat and Kathiawar","Kerala and Malabar"],"answer":0,"explanation":"Dharamdas of Bandhavgarh is regarded as the founder of the Chhattisgarh branch of the Kabir Panth, with its seat at Damakheda. The Panth spread mainly in the Gangetic plain and central India.","difficulty":"hard","questionHi":"कबीर के धनी शिष्य धर्मदास कबीर पंथ की किस क्षेत्र की शाखा के संस्थापक माने जाते हैं?","optionsHi":["छत्तीसगढ़ क्षेत्र","बंगाल और ओडिशा","गुजरात और काठियावाड़","केरल और मालाबार"],"explanationHi":"बांधवगढ़ के धर्मदास को कबीर पंथ की छत्तीसगढ़ शाखा का संस्थापक माना जाता है, जिसका केंद्र दामाखेड़ा है। पंथ मुख्यतः गंगा के मैदान और मध्य भारत में फैला।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-131","question":"Kabir's Bijak, the main scripture of the Kabir Panth, is arranged in three parts. They are:","options":["Sakhi, Sabda and Ramaini","Pad, Doha and Chaupai","Japji, Sohila and Rahiras","Vachana, Kirtana and Abhanga"],"answer":0,"explanation":"The Bijak is divided into the Ramaini, the Sabda and the Sakhi, three forms of Kabir's verse. The other sets of terms belong to the Sikh liturgy and to Marathi and Kannada devotional poetry.","difficulty":"hard","questionHi":"कबीर पंथ का मुख्य ग्रंथ बीजक किन तीन भागों में बँटा है?","optionsHi":["साखी, सबद और रमैनी","पद, दोहा और चौपाई","जपजी, सोहिला और रहिरास","वचन, कीर्तन और अभंग"],"explanationHi":"बीजक रमैनी, सबद और साखी, कबीर की वाणी के तीन रूपों में बँटा है। अन्य शब्द-समूह सिख प्रार्थना-पद्धति और मराठी तथा कन्नड़ भक्ति काव्य के हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-132","question":"Which of these was NOT one of the Panj Pyare, the five beloved ones who formed the first Khalsa in 1699?","options":["Daya Singh","Dharam Singh","Mohkam Singh","Fateh Singh"],"answer":3,"explanation":"The Panj Pyare were Daya Singh, Dharam Singh, Himmat Singh, Mohkam Singh and Sahib Singh. Fateh Singh was one of Guru Gobind Singh's sons, not one of the five.","difficulty":"very-hard","questionHi":"इनमें से कौन 1699 में पहला खालसा बनाने वाले पाँच प्यारों (पंज प्यारे) में शामिल नहीं था?","optionsHi":["दया सिंह","धरम सिंह","मोहकम सिंह","फतेह सिंह"],"explanationHi":"पंज प्यारे दया सिंह, धरम सिंह, हिम्मत सिंह, मोहकम सिंह और साहिब सिंह थे। फतेह सिंह गुरु गोबिंद सिंह के पुत्रों में से थे, पाँचों में नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-133","question":"Banda Singh Bahadur defeated the Mughal faujdar Wazir Khan in 1710 at the battle of:","options":["Bhangani, near Paonta Sahib","Anandpur, the Khalsa's early base","Chappar Chiri, near Sirhind","Muktsar, in south-western Punjab"],"answer":2,"explanation":"At Chappar Chiri near Sirhind in 1710 Banda Singh Bahadur defeated and killed Wazir Khan, who had ordered the execution of Guru Gobind Singh's younger sons. Bhangani (1686) and Muktsar (1705) were fought by the Guru.","difficulty":"hard","questionHi":"1710 में बंदा सिंह बहादुर ने मुगल फौजदार वज़ीर खान को किस युद्ध में हराया?","optionsHi":["भंगाणी, पांवटा साहिब के निकट","आनंदपुर, खालसा का आरंभिक केंद्र","चप्पड़ चिड़ी, सरहिंद के निकट","मुक्तसर, दक्षिण-पश्चिम पंजाब में"],"explanationHi":"1710 में सरहिंद के निकट चप्पड़ चिड़ी में बंदा सिंह बहादुर ने वज़ीर खान को हराकर मार डाला, जिसने गुरु गोबिंद सिंह के छोटे पुत्रों को मृत्युदंड दिलाया था। भंगाणी (1686) और मुक्तसर (1705) की लड़ाइयाँ गुरु ने लड़ीं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-134","question":"The Gurdwara Sis Ganj Sahib in Delhi marks the place where which Guru was executed in 1675?","options":["Guru Arjan Dev","Guru Tegh Bahadur","Guru Hargobind","Guru Har Krishan"],"answer":1,"explanation":"Guru Tegh Bahadur was executed at Chandni Chowk in 1675 on Aurangzeb's orders, and Sis Ganj Sahib marks the spot. Guru Arjan was executed at Lahore in 1606, and Guru Har Krishan died in Delhi of smallpox.","difficulty":"hard","questionHi":"दिल्ली का गुरुद्वारा शीश गंज साहिब उस स्थान को चिह्नित करता है जहाँ 1675 में किस गुरु को मृत्युदंड दिया गया?","optionsHi":["गुरु अर्जन देव","गुरु तेग बहादुर","गुरु हरगोबिंद","गुरु हर कृष्ण"],"explanationHi":"औरंगज़ेब के आदेश पर 1675 में गुरु तेग बहादुर को चाँदनी चौक में मृत्युदंड दिया गया और शीश गंज साहिब उसी स्थान को दर्शाता है। गुरु अर्जन को 1606 में लाहौर में मृत्युदंड मिला और गुरु हर कृष्ण की दिल्ली में चेचक से मृत्यु हुई।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-135","question":"During the war of succession of 1658, which Mughal prince did Guru Har Rai help, an act that angered Aurangzeb?","options":["Dara Shikoh","Shah Shuja","Murad Bakhsh","Muhammad Akbar"],"answer":0,"explanation":"Guru Har Rai is said to have aided Dara Shikoh during the fight for the throne, and Aurangzeb later summoned the Guru's son Ram Rai to Delhi. Shuja and Murad were Dara's brothers, and Muhammad Akbar was Aurangzeb's son.","difficulty":"very-hard","questionHi":"1658 के उत्तराधिकार-युद्ध में गुरु हर राय ने किस मुगल राजकुमार की सहायता की, जिससे औरंगज़ेब नाराज़ हुआ?","optionsHi":["दारा शिकोह","शाह शुजा","मुराद बख्श","मुहम्मद अकबर"],"explanationHi":"कहा जाता है कि गुरु हर राय ने गद्दी की लड़ाई में दारा शिकोह की सहायता की, और औरंगज़ेब ने बाद में गुरु के पुत्र राम राय को दिल्ली बुलाया। शुजा और मुराद दारा के भाई थे और मुहम्मद अकबर औरंगज़ेब का पुत्र था।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-136","question":"The Zafarnama, a Persian letter to Aurangzeb protesting against the breach of oaths by the Mughals, was written by:","options":["Guru Tegh Bahadur","Guru Arjan Dev","Guru Gobind Singh","Banda Singh Bahadur"],"answer":2,"explanation":"Guru Gobind Singh wrote the Zafarnama (Epistle of Victory) in Persian to Aurangzeb from Dina around 1705. It accuses the Mughals of treachery after the siege of Anandpur.","difficulty":"hard","questionHi":"मुगलों द्वारा शपथ तोड़े जाने का विरोध करने वाला औरंगज़ेब के नाम फारसी पत्र ज़फ़रनामा किसने लिखा?","optionsHi":["गुरु तेग बहादुर","गुरु अर्जन देव","गुरु गोबिंद सिंह","बंदा सिंह बहादुर"],"explanationHi":"गुरु गोबिंद सिंह ने लगभग 1705 में दीना से औरंगज़ेब को फारसी में ज़फ़रनामा (विजय-पत्र) लिखा। इसमें आनंदपुर की घेराबंदी के बाद मुगलों के विश्वासघात का आरोप है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-137","question":"Guru Hargobind, imprisoned by Jahangir in the Gwalior fort, secured the release of how many Hindu princes along with himself?","options":["12","52","84","108"],"answer":1,"explanation":"Tradition says that Guru Hargobind was released from Gwalior along with fifty-two Hindu princes who held on to his robe, and Sikhs celebrate this as Bandi Chhor Divas. The number is fixed in Sikh tradition as fifty-two.","difficulty":"hard","questionHi":"जहाँगीर द्वारा ग्वालियर के किले में बंदी बनाए गए गुरु हरगोबिंद अपने साथ कितने हिंदू राजाओं की रिहाई करा सके?","optionsHi":["12","52","84","108"],"explanationHi":"परंपरा के अनुसार गुरु हरगोबिंद ग्वालियर से बावन हिंदू राजाओं के साथ रिहा हुए जिन्होंने उनका चोगा थाम लिया था, और सिख इसे बंदी छोड़ दिवस के रूप में मनाते हैं। सिख परंपरा में यह संख्या बावन तय है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-138","question":"Guru Nanak's lifelong companion Bhai Mardana was a:","options":["Muslim minstrel who played the rabab","Brahmin scribe from Kashmir","Rajput soldier from Lahore","Jain merchant from Gujarat"],"answer":0,"explanation":"Mardana, a Muslim from a family of minstrels (mirasis), accompanied Guru Nanak on his travels and played the rabab while the Guru sang. This is a mark of the Guru's message of Hindu–Muslim harmony.","difficulty":"hard","questionHi":"गुरु नानक के आजीवन साथी भाई मरदाना कौन थे?","optionsHi":["रबाब बजाने वाले मुस्लिम गायक","कश्मीर के ब्राह्मण लिपिक","लाहौर के राजपूत सैनिक","गुजरात के जैन व्यापारी"],"explanationHi":"मरदाना भाटों (मीरासी) के परिवार के मुस्लिम थे जो गुरु नानक की यात्राओं में साथ रहे और गुरु के गायन के साथ रबाब बजाते थे। यह गुरु के हिंदू-मुस्लिम सद्भाव के संदेश का प्रतीक है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-139","question":"Guru Nanak's three principles were Naam Japo, Vand Chhako and Kirat Karo. 'Kirat Karo' means:","options":["Chant the divine name","Share with others","Earn by honest labour","Serve in the langar"],"answer":2,"explanation":"Kirat Karo means to earn one's living by honest work, Naam Japo means to remember God, and Vand Chhako means to share one's earnings with others.","difficulty":"moderate","questionHi":"गुरु नानक के तीन सिद्धांत नाम जपो, वंड छको और किरत करो थे। 'किरत करो' का अर्थ है:","optionsHi":["ईश्वर का नाम जपो","दूसरों के साथ बाँटो","ईमानदारी के श्रम से कमाओ","लंगर में सेवा करो"],"explanationHi":"किरत करो का अर्थ है ईमानदार श्रम से आजीविका कमाना, नाम जपो का अर्थ ईश्वर का स्मरण और वंड छको का अर्थ अपनी कमाई दूसरों के साथ बाँटना है।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-140","question":"The hymn Anand Sahib, recited at the end of Sikh ceremonies, was composed by:","options":["Guru Angad","Guru Nanak","Guru Amar Das","Guru Ram Das"],"answer":2,"explanation":"Anand Sahib, the hymn of bliss, was composed by the third Guru, Amar Das, and is a regular part of Sikh prayer. The Lavan was composed by Guru Ram Das.","difficulty":"hard","questionHi":"सिख समारोहों के अंत में पढ़ा जाने वाला भजन आनंद साहिब किसने रचा?","optionsHi":["गुरु अंगद","गुरु नानक","गुरु अमर दास","गुरु राम दास"],"explanationHi":"आनंद साहिब, आनंद का भजन, तीसरे गुरु अमर दास ने रचा और यह सिख प्रार्थना का नियमित भाग है। लावन गुरु राम दास ने रचा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-141","question":"The four Lavan hymns recited at the Sikh wedding ceremony (Anand Karaj) were composed by:","options":["Guru Amar Das","Guru Ram Das","Guru Arjan Dev","Guru Angad"],"answer":1,"explanation":"The Lavan, four stanzas that mark the rounds around the Guru Granth Sahib, was composed by the fourth Guru, Ram Das. The Anand hymn was composed by Amar Das.","difficulty":"very-hard","questionHi":"सिख विवाह संस्कार (आनंद कारज) में पढ़े जाने वाले चार लावन किसने रचे?","optionsHi":["गुरु अमर दास","गुरु राम दास","गुरु अर्जन देव","गुरु अंगद"],"explanationHi":"गुरु ग्रंथ साहिब की परिक्रमा के चार चरणों को दर्शाने वाले चार छंद लावन चौथे गुरु राम दास ने रचे। आनंद भजन अमर दास ने रचा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-142","question":"The Sukhmani Sahib, the 'Psalm of Peace' recited daily by many Sikhs, was composed by:","options":["Guru Arjan Dev","Guru Hargobind","Guru Tegh Bahadur","Guru Nanak"],"answer":0,"explanation":"Guru Arjan Dev, the fifth Guru, composed the Sukhmani Sahib, which is included in the Guru Granth Sahib. He also compiled the Adi Granth in 1604.","difficulty":"moderate","questionHi":"सुखमनी साहिब, 'शांति का भजन' जिसे अनेक सिख प्रतिदिन पढ़ते हैं, किसने रचा?","optionsHi":["गुरु अर्जन देव","गुरु हरगोबिंद","गुरु तेग बहादुर","गुरु नानक"],"explanationHi":"पाँचवें गुरु अर्जन देव ने सुखमनी साहिब रचा, जो गुरु ग्रंथ साहिब में शामिल है। उन्होंने 1604 में आदि ग्रंथ का संकलन भी किया।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-143","question":"Bhai Gurdas, whose Vars are called the 'key to the Guru Granth Sahib', was related to Guru Amar Das as his:","options":["Son","Brother","Grandson","Nephew"],"answer":3,"explanation":"Bhai Gurdas, the scribe and expositor of the Adi Granth, was a nephew of Guru Amar Das. His Vars in Punjabi are regarded as a key to the Sikh scripture.","difficulty":"very-hard","questionHi":"भाई गुरदास, जिनके वार 'गुरु ग्रंथ साहिब की कुंजी' कहलाते हैं, गुरु अमर दास के क्या लगते थे?","optionsHi":["पुत्र","भाई","पौत्र","भतीजे"],"explanationHi":"आदि ग्रंथ के लिपिक और व्याख्याता भाई गुरदास गुरु अमर दास के भतीजे थे। उनके पंजाबी वार सिख धर्मग्रंथ की कुंजी माने जाते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-144","question":"In the Chishti tradition, unsolicited charity received by a khanqah and distributed to the needy was called:","options":["Jizya","Zakat","Nazr","Futuh"],"answer":3,"explanation":"Futuh was unasked-for charity, which the Chishti saints accepted and distributed immediately, while refusing land grants and fixed stipends from rulers. This marked their distance from the state.","difficulty":"hard","questionHi":"चिश्ती परंपरा में खानकाह को मिलने वाला बिन माँगा दान, जो ज़रूरतमंदों में बाँट दिया जाता था, क्या कहलाता था?","optionsHi":["जजिया","ज़कात","नज़र","फुतूह"],"explanationHi":"फुतूह बिन माँगा दान था जिसे चिश्ती संत स्वीकार कर तुरंत बाँट देते थे, जबकि वे शासकों से भूमि-अनुदान और निश्चित वृत्ति नहीं लेते थे। यह राज्य से उनकी दूरी दर्शाता था।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-145","question":"In the Chishti silsila, the territory in which a pir's khalifa exercised spiritual authority was called:","options":["Wilayat","Tariqa","Urs","Sama"],"answer":0,"explanation":"A pir appointed a khalifa (successor) and assigned him a wilayat, a spiritual jurisdiction. Tariqa is the Sufi path or order, urs the death anniversary of a saint and sama the audition of devotional music.","difficulty":"very-hard","questionHi":"चिश्ती सिलसिले में वह क्षेत्र, जिसमें पीर का खलीफा आध्यात्मिक अधिकार रखता था, क्या कहलाता था?","optionsHi":["वलायत","तरीक़ा","उर्स","समा"],"explanationHi":"पीर अपना खलीफा (उत्तराधिकारी) नियुक्त करता और उसे वलायत, यानी आध्यात्मिक अधिकार-क्षेत्र, सौंपता था। तरीक़ा सूफी मार्ग या संप्रदाय है, उर्स संत की पुण्यतिथि और समा भक्ति संगीत का श्रवण है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-146","question":"In the Ain-i-Akbari, Abul Fazl lists how many Sufi silsilas?","options":["Eight","Fourteen","Twenty-two","Four"],"answer":1,"explanation":"Abul Fazl enumerated fourteen Sufi silsilas in the Ain-i-Akbari, among them the Chishti, Suhrawardi and Qadiri. The Sufi orders in India were thus many, not just the best-known two or three.","difficulty":"very-hard","questionHi":"आइन-ए-अकबरी में अबुल फज़ल ने कितने सूफी सिलसिले गिनाए हैं?","optionsHi":["आठ","चौदह","बाईस","चार"],"explanationHi":"अबुल फज़ल ने आइन-ए-अकबरी में चौदह सूफी सिलसिले गिनाए हैं, जिनमें चिश्ती, सुहरावर्दी और क़ादिरी शामिल हैं। इस प्रकार भारत में सूफी संप्रदाय केवल दो-तीन प्रसिद्ध नहीं, बल्कि अनेक थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-147","question":"'Hanuz Dilli dur ast' (Delhi is still far) is, by tradition, a warning of Nizamuddin Auliya to:","options":["Alauddin Khalji","Balban","Ghiyasuddin Tughlaq","Muhammad bin Tughlaq"],"answer":2,"explanation":"The saying is attributed to Nizamuddin Auliya in reply to Ghiyasuddin Tughlaq's threat to punish him on return from Bengal. The Sultan died in 1325 before reaching Delhi.","difficulty":"hard","questionHi":"'हनूज़ दिल्ली दूर अस्त' (दिल्ली अभी दूर है) परंपरा से निज़ामुद्दीन औलिया की किसे चेतावनी मानी जाती है?","optionsHi":["अलाउद्दीन खिलजी","बलबन","गियासुद्दीन तुगलक","मुहम्मद बिन तुगलक"],"explanationHi":"यह कथन निज़ामुद्दीन औलिया का माना जाता है, जो उन्होंने बंगाल से लौटकर उन्हें दंड देने की गियासुद्दीन तुगलक की धमकी के उत्तर में कहा। सुल्तान 1325 में दिल्ली पहुँचने से पहले मर गया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-148","question":"Dara Shikoh was a disciple of the Qadiri Sufi saints Mullah Shah Badakhshi and:","options":["Mian Mir","Nizamuddin Auliya","Shaikh Salim Chishti","Ahmad Sirhindi"],"answer":0,"explanation":"Dara Shikoh was initiated into the Qadiri order by Mian Mir of Lahore and then by Mullah Shah Badakhshi. He wrote Sakinat-ul-Auliya on Qadiri saints and the Majma-ul-Bahrain.","difficulty":"very-hard","questionHi":"दारा शिकोह क़ादिरी सूफी संत मुल्ला शाह बदख्शी और किसके शिष्य थे?","optionsHi":["मियाँ मीर","निज़ामुद्दीन औलिया","शेख सलीम चिश्ती","अहमद सरहिंदी"],"explanationHi":"दारा शिकोह ने क़ादिरी सिलसिले की दीक्षा लाहौर के मियाँ मीर और फिर मुल्ला शाह बदख्शी से ली। उन्होंने क़ादिरी संतों पर सकीनत-उल-औलिया और मज्मा-उल-बहरैन लिखी।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-149","question":"Gisu Daraz, the Chishti saint buried at Gulbarga, was a disciple of:","options":["Nizamuddin Auliya","Nasiruddin Chiragh-i-Dehli","Baba Farid","Qutbuddin Bakhtiyar Kaki"],"answer":1,"explanation":"Gisu Daraz (Banda Nawaz) was a disciple of Nasiruddin Chiragh-i-Dehli, the successor of Nizamuddin Auliya. He moved to the Deccan and was settled at Gulbarga under the Bahmani Sultans.","difficulty":"hard","questionHi":"गुलबर्गा में दफ़न चिश्ती संत गेसू दराज़ किसके शिष्य थे?","optionsHi":["निज़ामुद्दीन औलिया","नसीरुद्दीन चिराग़-ए-दिल्ली","बाबा फरीद","क़ुतुबुद्दीन बख़्तियार काकी"],"explanationHi":"गेसू दराज़ (बंदा नवाज़) निज़ामुद्दीन औलिया के उत्तराधिकारी नसीरुद्दीन चिराग़-ए-दिल्ली के शिष्य थे। वे दक्कन चले गए और बहमनी सुल्तानों के अधीन गुलबर्गा में बसे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-150","question":"The dargah of Alauddin Ali Ahmad Sabir, founder of the Sabiri branch of the Chishti order, stands at Kaliyar near:","options":["Roorkee","Ajmer","Pakpattan","Gwalior"],"answer":0,"explanation":"Sabir Kaliyari, a disciple and nephew of Baba Farid, founded the Sabiri branch, and his dargah stands at Kaliyar near Roorkee. Ajmer holds Moinuddin Chishti and Pakpattan Baba Farid.","difficulty":"very-hard","questionHi":"चिश्ती सिलसिले की साबिरी शाखा के संस्थापक अलाउद्दीन अली अहमद साबिर की दरगाह कलियर में किसके निकट है?","optionsHi":["रुड़की","अजमेर","पाकपट्टन","ग्वालियर"],"explanationHi":"बाबा फरीद के शिष्य और भांजे साबिर कलियरी ने साबिरी शाखा की स्थापना की और उनकी दरगाह रुड़की के निकट कलियर में है। अजमेर में मोइनुद्दीन चिश्ती और पाकपट्टन में बाबा फरीद की दरगाह है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-151","question":"Mir Sayyid Ali Hamadani (Shah-i-Hamadan), who came to Kashmir in the 14th century, spread which Sufi order?","options":["Kubrawiya","Chishti","Suhrawardi","Naqshbandi"],"answer":0,"explanation":"Mir Sayyid Ali Hamadani of Persia belonged to the Kubrawiya order and brought it to Kashmir, along with Persian crafts and culture. The Rishi order grew out of the local tradition of Nund Rishi.","difficulty":"very-hard","questionHi":"14वीं शताब्दी में कश्मीर आए मीर सैयद अली हमदानी (शाह-ए-हमदान) ने किस सूफी सिलसिले का प्रसार किया?","optionsHi":["कुबरविया","चिश्ती","सुहरावर्दी","नक्शबंदी"],"explanationHi":"फारस के मीर सैयद अली हमदानी कुबरविया सिलसिले के थे और उसे फारसी शिल्प तथा संस्कृति के साथ कश्मीर लाए। ऋषि संप्रदाय नुंद ऋषि की स्थानीय परंपरा से विकसित हुआ।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-152","question":"The Haji Ali Dargah in Mumbai, built on an islet off the coast, is the tomb of Pir:","options":["Makhdoom Ali Mahimi","Moinuddin Chishti","Nizamuddin Auliya","Haji Ali Shah Bukhari"],"answer":3,"explanation":"The dargah is the tomb of Haji Ali Shah Bukhari, a wealthy merchant from Bukhara who became a saint. Makhdoom Ali Mahimi is the saint of the Mahim dargah elsewhere in Mumbai.","difficulty":"hard","questionHi":"मुंबई में समुद्र के किनारे एक टापू पर बनी हाजी अली दरगाह किस पीर का मकबरा है?","optionsHi":["मखदूम अली माहिमी","मोइनुद्दीन चिश्ती","निज़ामुद्दीन औलिया","हाजी अली शाह बुखारी"],"explanationHi":"यह दरगाह बुखारा के धनी व्यापारी हाजी अली शाह बुखारी की समाधि है, जो संत बन गए थे। मखदूम अली माहिमी मुंबई में अन्यत्र माहिम दरगाह के संत हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-153","question":"Sheikh Abdul Quddus Gangohi, a 16th-century saint buried at Gangoh, belonged to which branch of the Chishti order?","options":["Sabiri","Nizami","Ashrafi","Fakhri"],"answer":0,"explanation":"Abdul Quddus Gangohi was a leading saint of the Chishti-Sabiri branch, and his verses and letters in Hindavi show its local roots. The Nizami branch descended from Nizamuddin Auliya.","difficulty":"very-hard","questionHi":"गंगोह में दफ़न 16वीं शताब्दी के संत शेख अब्दुल क़ुद्दूस गंगोही चिश्ती सिलसिले की किस शाखा के थे?","optionsHi":["साबिरी","निज़ामी","अशरफ़ी","फ़ख़री"],"explanationHi":"अब्दुल क़ुद्दूस गंगोही चिश्ती-साबिरी शाखा के प्रमुख संत थे और हिंदवी में उनकी कविताएँ तथा पत्र उसकी स्थानीय जड़ें दर्शाते हैं। निज़ामी शाखा निज़ामुद्दीन औलिया से चली।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-154","question":"Srikrishnakirtan, an early Bengali narrative poem on the love of Radha and Krishna, is attributed to:","options":["Vidyapati","Baru Chandidas","Jayadeva","Govindadasa"],"answer":1,"explanation":"The Srikrishnakirtan, discovered in a manuscript at Bankura, is attributed to Baru Chandidas of the 14th–15th centuries. Vidyapati wrote in Maithili and Jayadeva in Sanskrit.","difficulty":"hard","questionHi":"श्रीकृष्णकीर्तन, राधा-कृष्ण के प्रेम पर आरंभिक बंगला आख्यानक काव्य, किसकी रचना माना जाता है?","optionsHi":["विद्यापति","बड़ु चंडीदास","जयदेव","गोविंददास"],"explanationHi":"बाँकुड़ा की पांडुलिपि में मिला श्रीकृष्णकीर्तन चौदहवीं-पंद्रहवीं शताब्दी के बड़ु चंडीदास की रचना माना जाता है। विद्यापति ने मैथिली में और जयदेव ने संस्कृत में लिखा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-155","question":"Sri Rama Panchali, the Bengali Ramayana, was composed by:","options":["Chandidas","Maladhar Basu","Krittibas Ojha","Kashiram Das"],"answer":2,"explanation":"Krittibas Ojha of the 15th century composed the Bengali Ramayana, popularly called Krittibasi Ramayana. Kashiram Das is the author of the Bengali Mahabharata and Maladhar Basu of the Sri Krishna Vijaya.","difficulty":"hard","questionHi":"बंगला रामायण 'श्रीराम पांचाली' किसने रची?","optionsHi":["चंडीदास","मालाधर बसु","कृत्तिवास ओझा","काशीराम दास"],"explanationHi":"पंद्रहवीं शताब्दी के कृत्तिवास ओझा ने बंगला रामायण रची, जो कृत्तिवासी रामायण के नाम से लोकप्रिय है। काशीराम दास बंगला महाभारत के और मालाधर बसु श्रीकृष्ण विजय के रचयिता हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-156","question":"Match the Malayalam work with its author: A. Adhyatma Ramayanam Kilippattu B. Narayaneeyam C. Jnanappana D. Krishnagatha. Authors: 1. Poonthanam 2. Cherusseri 3. Melpathur Narayana Bhattathiri 4. Thunchaththu Ezhuthachan","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2"],"answer":3,"explanation":"Ezhuthachan wrote the Adhyatma Ramayanam Kilippattu, Melpathur Narayana Bhattathiri the Sanskrit Narayaneeyam, Poonthanam the Jnanappana and Cherusseri the Krishnagatha. Bhakti flourished in Kerala in several languages.","difficulty":"very-hard","questionHi":"मलयालम रचना का उसके लेखक से मिलान कीजिए: A. अध्यात्म रामायणम् किलिप्पाट्टु B. नारायणीयम् C. ज्ञानप्पाना D. कृष्णगाथा। लेखक: 1. पूंथानम 2. चेरुश्शेरी 3. मेलपत्तूर नारायण भट्टतिरि 4. तुंचत्तु एऴुत्तच्छन","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2"],"explanationHi":"एऴुत्तच्छन ने अध्यात्म रामायणम् किलिप्पाट्टु, मेलपत्तूर नारायण भट्टतिरि ने संस्कृत का नारायणीयम्, पूंथानम ने ज्ञानप्पाना और चेरुश्शेरी ने कृष्णगाथा लिखी। केरल में भक्ति अनेक भाषाओं में फली-फूली।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-157","question":"The Hatha Yoga Pradipika, a classic text of hatha yoga, was composed by Svatmarama, who belonged to the:","options":["Kabir Panth","Nath tradition","Dadu Panth","Varkari tradition"],"answer":1,"explanation":"Svatmarama compiled the Hatha Yoga Pradipika in the 15th century as part of the Nath tradition of Matsyendranath and Gorakhnath. The other groups are Nirguna and Marathi devotional traditions.","difficulty":"very-hard","questionHi":"हठयोग का प्रमुख ग्रंथ हठयोग प्रदीपिका स्वात्माराम ने रचा, जो किस परंपरा के थे?","optionsHi":["कबीर पंथ","नाथ परंपरा","दादू पंथ","वारकरी परंपरा"],"explanationHi":"स्वात्माराम ने पंद्रहवीं शताब्दी में मत्स्येंद्रनाथ और गोरखनाथ की नाथ परंपरा के अंग के रूप में हठयोग प्रदीपिका संकलित की। अन्य समूह निर्गुण और मराठी भक्ति परंपराएँ हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-158","question":"The Bachittar Natak, a work of the Dasam Granth, is:","options":["A Persian letter to Aurangzeb","A hymn collection of Guru Tegh Bahadur","An autobiographical account by Guru Gobind Singh","A biography of Guru Nanak by Bhai Gurdas"],"answer":2,"explanation":"The Bachittar Natak is Guru Gobind Singh's autobiographical account of his lineage and mission, included in the Dasam Granth. The Persian letter to Aurangzeb is the Zafarnama.","difficulty":"very-hard","questionHi":"दसम ग्रंथ की रचना बचित्तर नाटक क्या है?","optionsHi":["औरंगज़ेब को लिखा फारसी पत्र","गुरु तेग बहादुर के भजनों का संग्रह","गुरु गोबिंद सिंह का आत्मकथात्मक वृत्तांत","भाई गुरदास द्वारा गुरु नानक की जीवनी"],"explanationHi":"बचित्तर नाटक गुरु गोबिंद सिंह का अपने वंश और उद्देश्य का आत्मकथात्मक वृत्तांत है, जो दसम ग्रंथ में शामिल है। औरंगज़ेब को लिखा फारसी पत्र ज़फ़रनामा है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-159","question":"The Bishnoi sect, founded in 1485, takes its name from its twenty-nine tenets that stress protection of trees and animals. Its founder was:","options":["Dadu Dayal","Charandas","Pipa","Jambhoji"],"answer":3,"explanation":"Jambhoji (Guru Jambheshwar) founded the Bishnoi sect in the Thar desert region, and its tenets include protecting trees and animals. The Bishnoi of Khejarli famously gave their lives in 1730 to save khejri trees.","difficulty":"moderate","questionHi":"1485 में स्थापित बिश्नोई पंथ अपने उनतीस नियमों से नाम पाता है, जो पेड़ों और पशुओं की रक्षा पर बल देते हैं। इसके संस्थापक कौन थे?","optionsHi":["दादू दयाल","चरणदास","पीपा","जांभोजी"],"explanationHi":"जांभोजी (गुरु जांभेश्वर) ने थार मरुस्थल क्षेत्र में बिश्नोई पंथ की स्थापना की, जिसके नियमों में पेड़ों और पशुओं की रक्षा शामिल है। खेजड़ली के बिश्नोइयों ने 1730 में खेजड़ी के पेड़ बचाने के लिए प्राण दिए थे।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-160","question":"Ramprasadi songs, devotional hymns addressed to the Mother Goddess Kali, are the work of:","options":["Chandidas","Lalon Fakir","Ramprasad Sen","Bharatchandra"],"answer":2,"explanation":"Ramprasad Sen of 18th-century Bengal composed the Shakta songs known as Ramprasadi, addressing Kali as a mother. Bharatchandra was a court poet who wrote the Annadamangal.","difficulty":"hard","questionHi":"देवी काली को संबोधित भक्ति गीत रामप्रसादी किसकी रचना हैं?","optionsHi":["चंडीदास","लालन फकीर","रामप्रसाद सेन","भारतचंद्र"],"explanationHi":"अठारहवीं शताब्दी के बंगाल के रामप्रसाद सेन ने काली को माँ के रूप में संबोधित करने वाले शाक्त गीत रचे, जो रामप्रसादी कहलाते हैं। भारतचंद्र दरबारी कवि थे जिन्होंने अन्नदामंगल लिखा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-161","question":"Which of these is a Baul saint-poet of Bengal whose songs reject caste and religious divisions?","options":["Bulleh Shah","Lalon Fakir","Dadu Dayal","Sant Tukaram"],"answer":1,"explanation":"Lalon Fakir of Kushtia was a celebrated Baul whose songs reject caste and communal barriers. Bulleh Shah was a Punjabi Sufi, Dadu a Nirguna saint of Rajasthan and Tukaram a Varkari saint.","difficulty":"moderate","questionHi":"इनमें से कौन बंगाल का बाउल संत-कवि है जिसके गीत जाति और धर्म के भेदों को नकारते हैं?","optionsHi":["बुल्ले शाह","लालन फकीर","दादू दयाल","संत तुकाराम"],"explanationHi":"कुश्तिया के लालन फकीर प्रसिद्ध बाउल थे जिनके गीत जाति और सांप्रदायिक बाधाओं को नकारते हैं। बुल्ले शाह पंजाबी सूफी, दादू राजस्थान के निर्गुण संत और तुकाराम वारकरी संत थे।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-162","question":"Abhinavagupta, author of the Tantraloka, was a philosopher of:","options":["Kashmir Shaivism","Virashaivism","Pancharatra Vaishnavism","Pashupata Shaivism"],"answer":0,"explanation":"Abhinavagupta of Kashmir, around 1000 CE, was the greatest exponent of Kashmir Shaivism and wrote the Tantraloka and works on aesthetics. Virashaivism arose in Karnataka much later.","difficulty":"hard","questionHi":"तंत्रालोक के रचयिता अभिनवगुप्त किस दर्शन के आचार्य थे?","optionsHi":["कश्मीर शैव दर्शन","वीरशैव मत","पांचरात्र वैष्णव मत","पाशुपत शैव मत"],"explanationHi":"लगभग 1000 ईस्वी के कश्मीरी अभिनवगुप्त कश्मीर शैव दर्शन के सबसे बड़े आचार्य थे और उन्होंने तंत्रालोक तथा सौंदर्यशास्त्र पर ग्रंथ लिखे। वीरशैव मत कर्नाटक में बहुत बाद में उभरा।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-163","question":"Meykandar, author of the Sivajnanabodham in the 13th century, is the great exponent of:","options":["Advaita Vedanta","Dvaita Vedanta","Vishishtadvaita","Shaiva Siddhanta"],"answer":3,"explanation":"Meykandar's Sivajnanabodham is the foundation text of Tamil Shaiva Siddhanta, which teaches the reality of God, soul and bondage. Advaita belongs to Shankara, Vishishtadvaita to Ramanuja and Dvaita to Madhva.","difficulty":"very-hard","questionHi":"13वीं शताब्दी में शिवज्ञानबोधम् के रचयिता मेय्कंडार किस दर्शन के महान व्याख्याता हैं?","optionsHi":["अद्वैत वेदांत","द्वैत वेदांत","विशिष्टाद्वैत","शैव सिद्धांत"],"explanationHi":"मेय्कंडार का शिवज्ञानबोधम् तमिल शैव सिद्धांत का आधार-ग्रंथ है, जो ईश्वर, जीव और बंधन की वास्तविकता सिखाता है। अद्वैत शंकर का, विशिष्टाद्वैत रामानुज का और द्वैत मध्व का दर्शन है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-164","question":"Ramanuja's commentary on the Brahma Sutra, which expounds Vishishtadvaita, is called the:","options":["Sariraka Bhashya","Sri Bhashya","Anu Bhashya","Purnaprajna Bhashya"],"answer":1,"explanation":"Ramanuja's Sri Bhashya is his commentary on the Brahma Sutra. Sariraka Bhashya is Shankara's, Anu Bhashya is Vallabha's and Purnaprajna Bhashya is Madhva's.","difficulty":"hard","questionHi":"ब्रह्मसूत्र पर रामानुज की टीका, जिसमें विशिष्टाद्वैत की व्याख्या है, क्या कहलाती है?","optionsHi":["शारीरक भाष्य","श्रीभाष्य","अणुभाष्य","पूर्णप्रज्ञ भाष्य"],"explanationHi":"रामानुज का श्रीभाष्य ब्रह्मसूत्र पर उनकी टीका है। शारीरक भाष्य शंकर का, अणुभाष्य वल्लभ का और पूर्णप्रज्ञ भाष्य मध्व का है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-165","question":"Abdur Rahim Khan-i-Khanan, famed for his Hindi couplets (dohe) and a leading noble of Akbar, was the son of:","options":["Todar Mal","Man Singh","Bairam Khan","Birbal"],"answer":2,"explanation":"Rahim was the son of Bairam Khan, Akbar's regent, and became Khan-i-Khanan, a noble, general and poet. His Hindi dohas on worldly wisdom and devotion are still widely quoted.","difficulty":"moderate","questionHi":"अब्दुर्रहीम खान-ए-खाना, जो अपने हिंदी दोहों के लिए प्रसिद्ध और अकबर के प्रमुख अमीर थे, किसके पुत्र थे?","optionsHi":["टोडरमल","मान सिंह","बैरम खाँ","बीरबल"],"explanationHi":"रहीम अकबर के संरक्षक बैरम खाँ के पुत्र थे और खान-ए-खाना बने, जो अमीर, सेनापति और कवि थे। सांसारिक ज्ञान और भक्ति पर उनके हिंदी दोहे आज भी प्रसिद्ध हैं।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-166","question":"The bharud, an allegorical folk song form used to teach devotion in Marathi, was popularised by:","options":["Namdev","Tukaram","Ramdas","Eknath"],"answer":3,"explanation":"Eknath of Paithan composed bharuds, humorous and allegorical songs, to carry devotion to ordinary people, and he also wrote the Eknathi Bhagavata. Namdev and Tukaram are known chiefly for abhangas.","difficulty":"very-hard","questionHi":"भारुड, मराठी में भक्ति सिखाने वाली रूपकात्मक लोकगीत शैली, को किसने लोकप्रिय बनाया?","optionsHi":["नामदेव","तुकाराम","रामदास","एकनाथ"],"explanationHi":"पैठण के एकनाथ ने भक्ति को साधारण जनों तक पहुँचाने के लिए हास्यपूर्ण और रूपकात्मक भारुड रचे और एकनाथी भागवत भी लिखा। नामदेव और तुकाराम मुख्यतः अभंगों के लिए जाने जाते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-167","question":"Which of these was NOT among the Ashtachhap, the eight poets of the Pushtimarg tradition?","options":["Kumbhandas","Paramanandadas","Tulsidas","Nanddas"],"answer":2,"explanation":"The Ashtachhap included Surdas, Kumbhandas, Paramanandadas, Krishnadas, Nanddas, Chaturbhujdas, Govindaswami and Chhitaswami. Tulsidas was a Rama devotee outside the Pushtimarg.","difficulty":"hard","questionHi":"इनमें से कौन पुष्टिमार्ग परंपरा के आठ कवियों अष्टछाप में शामिल नहीं था?","optionsHi":["कुंभनदास","परमानंददास","तुलसीदास","नंददास"],"explanationHi":"अष्टछाप में सूरदास, कुंभनदास, परमानंददास, कृष्णदास, नंददास, चतुर्भुजदास, गोविंदस्वामी और छीतस्वामी थे। तुलसीदास राम-भक्त थे और पुष्टिमार्ग से बाहर थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-168","question":"Pipa, the king-turned-saint and disciple of Ramananda, ruled the fort of:","options":["Chittor, the Sisodia citadel of Mewar","Gagraungarh, the Khichi fort","Amber, the Kachhwaha capital","Mandu, the Malwa hill-fort"],"answer":1,"explanation":"Pipa was a Rajput ruler of Gagraungarh who gave up his kingdom to follow Ramananda, and one of his hymns is in the Guru Granth Sahib. Chittor, Amber and Mandu belonged to other dynasties.","difficulty":"very-hard","questionHi":"रामानंद के शिष्य राजा से संत बने पीपा किस किले के शासक थे?","optionsHi":["चित्तौड़, मेवाड़ का सिसोदिया दुर्ग","गागरोन, खींची दुर्ग","आमेर, कछवाहा राजधानी","मांडू, मालवा का पहाड़ी किला"],"explanationHi":"पीपा गागरोन के राजपूत शासक थे जिन्होंने रामानंद का अनुसरण करने के लिए राज्य छोड़ दिया और उनका एक भजन गुरु ग्रंथ साहिब में है। चित्तौड़, आमेर और मांडू अन्य वंशों के थे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-169","question":"The Bhagavata Purana, central to Vaishnava devotion to Krishna, is generally believed to have been composed in:","options":["South India, around the 10th century","Gandhara, during the Kushan period","Kashmir, during the Gupta period","Bengal, around the 14th century"],"answer":0,"explanation":"Scholars generally place the Bhagavata Purana in South India, probably the Tamil region, around the 9th–10th centuries, which links it to the Alvar tradition. It then became the text of Krishna bhakti across the north.","difficulty":"hard","questionHi":"कृष्ण की वैष्णव भक्ति का केंद्रीय ग्रंथ भागवत पुराण सामान्यतः कहाँ रचा गया माना जाता है?","optionsHi":["दक्षिण भारत में, लगभग 10वीं शताब्दी में","गांधार में, कुषाण काल में","कश्मीर में, गुप्त काल में","बंगाल में, लगभग 14वीं शताब्दी में"],"explanationHi":"विद्वान सामान्यतः भागवत पुराण को दक्षिण भारत, संभवतः तमिल क्षेत्र, में लगभग नौवीं-दसवीं शताब्दी का मानते हैं, जो इसे आलवार परंपरा से जोड़ता है। बाद में यह उत्तर भर में कृष्ण भक्ति का ग्रंथ बना।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-170","question":"Match the event with the Sikh Guru: A. Wearing of two swords (Miri and Piri) B. Creation of the Khalsa C. Compilation of the Adi Granth D. Martyrdom at Delhi in 1675. Gurus: 1. Guru Arjan Dev 2. Guru Hargobind 3. Guru Tegh Bahadur 4. Guru Gobind Singh","options":["A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"answer":2,"explanation":"Guru Hargobind wore the two swords of spiritual and temporal authority, Guru Gobind Singh founded the Khalsa in 1699, Guru Arjan Dev compiled the Adi Granth in 1604 and Guru Tegh Bahadur was executed in Delhi in 1675.","difficulty":"very-hard","questionHi":"घटना का सिख गुरु से मिलान कीजिए: A. दो तलवारें (मीरी और पीरी) धारण करना B. खालसा की स्थापना C. आदि ग्रंथ का संकलन D. 1675 में दिल्ली में शहादत। गुरु: 1. गुरु अर्जन देव 2. गुरु हरगोबिंद 3. गुरु तेग बहादुर 4. गुरु गोबिंद सिंह","optionsHi":["A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"explanationHi":"गुरु हरगोबिंद ने आध्यात्मिक और लौकिक सत्ता की दो तलवारें धारण कीं, गुरु गोबिंद सिंह ने 1699 में खालसा की स्थापना की, गुरु अर्जन देव ने 1604 में आदि ग्रंथ का संकलन किया और गुरु तेग बहादुर को 1675 में दिल्ली में मृत्युदंड मिला।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-171","question":"Arrange in chronological order: 1. Compilation of the Ramcharitmanas 2. Composition of the Gita Govinda 3. Compilation of the Adi Granth 4. Composition of the Jnaneshwari","options":["2-1-4-3","2-4-1-3","4-2-1-3","2-4-3-1"],"answer":1,"explanation":"The Gita Govinda dates to the 12th century, the Jnaneshwari to 1290, the Ramcharitmanas to 1574 and the Adi Granth to 1604.","difficulty":"very-hard","questionHi":"कालक्रम में व्यवस्थित कीजिए: 1. रामचरितमानस की रचना 2. गीत गोविंद की रचना 3. आदि ग्रंथ का संकलन 4. ज्ञानेश्वरी की रचना","optionsHi":["2-1-4-3","2-4-1-3","4-2-1-3","2-4-3-1"],"explanationHi":"गीत गोविंद बारहवीं शताब्दी का, ज्ञानेश्वरी 1290 की, रामचरितमानस 1574 का और आदि ग्रंथ 1604 का है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-172","question":"Assertion (A): The Chishti saints generally kept their distance from the state. Reason (R): They refused land grants from rulers and accepted only unsolicited gifts, which they distributed to the needy.","options":["A is true, but R is false","Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false, but R is true"],"answer":1,"explanation":"The Chishti saints refused jagirs and fixed stipends and lived on unasked gifts (futuh) that they gave away, which was how they kept their independence from the Sultans.","difficulty":"hard","questionHi":"अभिकथन (A): चिश्ती संत प्रायः राज्य से दूरी बनाए रखते थे। कारण (R): वे शासकों से भूमि-अनुदान अस्वीकार करते थे और केवल बिन माँगे उपहार लेते थे जिन्हें वे ज़रूरतमंदों में बाँट देते थे।","optionsHi":["A सही है, पर R गलत है","A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, पर R, A की सही व्याख्या नहीं है","A गलत है, पर R सही है"],"explanationHi":"चिश्ती संत जागीर और निश्चित वृत्ति अस्वीकार करते थे और बिन माँगे उपहार (फुतूह) पर जीते थे जिन्हें वे बाँट देते थे, इसी से वे सुल्तानों से स्वतंत्र रहे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-173","question":"How many of these statements about the Guru Granth Sahib are correct? I. The Adi Granth was compiled by Guru Arjan Dev in 1604. II. The hymns of Guru Tegh Bahadur were added later by Guru Gobind Singh. III. It includes the verses of Mirabai. IV. It includes the compositions of Tulsidas.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. The Guru Granth Sahib contains hymns of Kabir, Namdev, Ravidas and Baba Farid, but not of Mirabai or Tulsidas.","difficulty":"very-hard","questionHi":"गुरु ग्रंथ साहिब के बारे में इनमें से कितने कथन सही हैं? I. आदि ग्रंथ का संकलन गुरु अर्जन देव ने 1604 में किया। II. गुरु तेग बहादुर के भजन बाद में गुरु गोबिंद सिंह ने जोड़े। III. इसमें मीराबाई की वाणी शामिल है। IV. इसमें तुलसीदास की रचनाएँ शामिल हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। गुरु ग्रंथ साहिब में कबीर, नामदेव, रविदास और बाबा फरीद की वाणी है, पर मीराबाई या तुलसीदास की नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-174","question":"How many of these statements about the Varkari tradition are correct? I. Pandharpur is its main centre of pilgrimage. II. Namdev and Tukaram are among its saints. III. Its saints composed mainly in Sanskrit. IV. It stressed the equality of devotees irrespective of caste.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. The Varkari saints composed their abhangas in Marathi, not in Sanskrit, in order to reach ordinary people.","difficulty":"very-hard","questionHi":"वारकरी परंपरा के बारे में इनमें से कितने कथन सही हैं? I. पंढरपुर इसका मुख्य तीर्थ-केंद्र है। II. नामदेव और तुकाराम इसके संतों में हैं। III. इसके संतों ने मुख्यतः संस्कृत में रचना की। IV. इसने जाति के भेद के बिना भक्तों की समानता पर बल दिया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। वारकरी संतों ने साधारण जन तक पहुँचने के लिए अपने अभंग संस्कृत में नहीं, बल्कि मराठी में रचे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-175","question":"The hymns of which of these Bhakti saints are NOT included in the Guru Granth Sahib?","options":["Ravidas","Namdev","Pipa","Mirabai"],"answer":3,"explanation":"The Guru Granth Sahib contains hymns of Ravidas, Namdev and Pipa among other Bhagats, but none of Mirabai. She belongs to the Krishna-devotion tradition of Rajasthan.","difficulty":"hard","questionHi":"इनमें से किस भक्त संत की वाणी गुरु ग्रंथ साहिब में शामिल नहीं है?","optionsHi":["रविदास","नामदेव","पीपा","मीराबाई"],"explanationHi":"गुरु ग्रंथ साहिब में अन्य भगतों के साथ रविदास, नामदेव और पीपा की वाणी है, पर मीराबाई की कोई वाणी नहीं। वे राजस्थान की कृष्ण-भक्ति परंपरा की हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-176","question":"Adi Shankara was born at:","options":["Kanchipuram in Tamil Nadu","Sringeri in Karnataka","Ujjain in Madhya Pradesh","Kaladi in Kerala"],"answer":3,"explanation":"Adi Shankara is traditionally said to have been born at Kaladi on the banks of the Periyar in Kerala. He later travelled across India and founded the four mathas.","difficulty":"moderate","questionHi":"आदि शंकर का जन्म कहाँ हुआ था?","optionsHi":["तमिलनाडु का कांचीपुरम","कर्नाटक का शृंगेरी","मध्य प्रदेश का उज्जैन","केरल का कालडी"],"explanationHi":"परंपरा के अनुसार आदि शंकर का जन्म केरल में पेरियार नदी के तट पर कालडी में हुआ। बाद में उन्होंने पूरे भारत की यात्रा की और चार मठ स्थापित किए।","source":"SSC CGL · UPSC Prelims"},
  {"id":"history-bhakti-sufi-177","question":"Tiruvaymoli, regarded as the Tamil Veda of the Vaishnavas, was composed by:","options":["Periyalvar","Tirumangai Alvar","Nammalvar","Tondaradippodi Alvar"],"answer":2,"explanation":"Nammalvar composed the Tiruvaymoli, the longest and most revered part of the Nalayira Divya Prabandham. Periyalvar is the father of Andal.","difficulty":"hard","questionHi":"वैष्णवों का तमिल वेद माने जाने वाला तिरुवाय्मोऴि किसने रचा?","optionsHi":["पेरियाळवार","तिरुमंगै आळवार","नम्माळवार","तोंडरडिप्पोडि आळवार"],"explanationHi":"नम्माळवार ने तिरुवाय्मोऴि रचा, जो नालायिर दिव्य प्रबंधम् का सबसे लंबा और सबसे पूज्य भाग है। पेरियाळवार आंडाल के पिता हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-178","question":"The Tevaram hymns of Sambandar, Appar and Sundarar were collected and arranged in the Chola period by:","options":["Nambiyandar Nambi","Sekkizhar","Nathamuni","Manikkavacakar"],"answer":0,"explanation":"Nambiyandar Nambi, under Rajaraja I, arranged the hymns of the three Nayanars as the Tevaram. Sekkizhar wrote the Periya Puranam, and Nathamuni compiled the Alvar hymns.","difficulty":"very-hard","questionHi":"संबंदर, अप्पर और सुंदरर के तेवारम् भजनों को चोल काल में किसने संकलित और व्यवस्थित किया?","optionsHi":["नंबियांडार नंबि","शेक्किऴार","नाथमुनि","माणिक्कवाचकर"],"explanationHi":"नंबियांडार नंबि ने राजराज प्रथम के समय तीनों नायनारों के भजनों को तेवारम् के रूप में व्यवस्थित किया। शेक्किऴार ने पेरिय पुराणम् लिखा और नाथमुनि ने आळवारों के भजन संकलित किए।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-179","question":"Sheikh Hamiduddin Nagauri, a Chishti saint of Nagaur, was known for:","options":["Accepting the patronage of the Sultan's court at Delhi and Nagaur","Writing the Fawaid-ul-Fuad, the discourses of Nizamuddin Auliya","Founding the Qadiri order in Rajasthan and Sindh, with many disciples","A strictly vegetarian life, farming a small plot for his living"],"answer":3,"explanation":"Hamiduddin Nagauri, a disciple of Moinuddin Chishti, lived as a vegetarian peasant on a small plot of land and refused patronage. Fawaid-ul-Fuad was compiled by Amir Hasan Sijzi.","difficulty":"very-hard","questionHi":"नागौर के चिश्ती संत शेख हमीदुद्दीन नागौरी किसके लिए जाने जाते थे?","optionsHi":["दिल्ली और नागौर में सुल्तान के दरबार का संरक्षण स्वीकार करने के लिए","निज़ामुद्दीन औलिया के प्रवचनों के संग्रह फवाइद-उल-फुआद को लिखने के लिए","राजस्थान और सिंध में कई शिष्यों के साथ क़ादिरी सिलसिला स्थापित करने के लिए","कठोर शाकाहारी जीवन और छोटे भूखंड पर खेती से आजीविका के लिए"],"explanationHi":"मोइनुद्दीन चिश्ती के शिष्य हमीदुद्दीन नागौरी छोटे भूखंड पर खेती करने वाले शाकाहारी किसान के रूप में रहे और उन्होंने संरक्षण ठुकराया। फवाइद-उल-फुआद अमीर हसन सिजज़ी ने संकलित की।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-180","question":"Sri Chand, the son of Guru Nanak, founded the:","options":["Nirmala sect","Udasi sect","Sevapanthi sect","Namdhari sect"],"answer":1,"explanation":"Sri Chand, Guru Nanak's elder son, founded the Udasi sect of ascetics, who stress renunciation. The Namdharis arose in the 19th century under Baba Ram Singh.","difficulty":"hard","questionHi":"गुरु नानक के पुत्र श्रीचंद ने किस पंथ की स्थापना की?","optionsHi":["निर्मला पंथ","उदासी पंथ","सेवापंथी पंथ","नामधारी पंथ"],"explanationHi":"गुरु नानक के बड़े पुत्र श्रीचंद ने तपस्वियों के उदासी पंथ की स्थापना की, जो त्याग पर बल देते हैं। नामधारी उन्नीसवीं शताब्दी में बाबा राम सिंह के नेतृत्व में उभरे।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-181","question":"Which of these is NOT one of the five Ks of the Khalsa?","options":["Khanda","Kesh","Kangha","Kara"],"answer":0,"explanation":"The five Ks are kesh (uncut hair), kangha (comb), kara (steel bracelet), kachera (undergarment) and kirpan (sword). The khanda is a double-edged sword and the Sikh emblem, not one of the five Ks.","difficulty":"moderate","questionHi":"इनमें से कौन खालसा के पाँच ककारों में शामिल नहीं है?","optionsHi":["खंडा","केश","कंघा","कड़ा"],"explanationHi":"पाँच ककार केश (बिना कटे बाल), कंघा, कड़ा (इस्पात का कंगन), कछैरा और कृपाण हैं। खंडा दुधारी तलवार और सिख प्रतीक है, पाँच ककारों में नहीं।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-182","question":"Kanhopatra, a woman saint of the Varkari tradition, was the daughter of a:","options":["Brahmin priest of Pandharpur","Weaver of Paithan","Courtesan of Mangalvedha","Potter of Dehu"],"answer":2,"explanation":"Kanhopatra, daughter of a courtesan of Mangalvedha, refused to serve the Sultan of Bidar's court and took refuge in the Vitthal temple at Pandharpur. She is remembered as a devotee who defied her social position.","difficulty":"very-hard","questionHi":"वारकरी परंपरा की संत कान्होपात्रा किसकी पुत्री थीं?","optionsHi":["पंढरपुर के ब्राह्मण पुजारी की","पैठण के बुनकर की","मंगलवेढ़ा की गणिका की","देहू के कुम्हार की"],"explanationHi":"मंगलवेढ़ा की गणिका की पुत्री कान्होपात्रा ने बीदर के सुल्तान के दरबार की सेवा से इनकार किया और पंढरपुर के विट्ठल मंदिर में शरण ली। उन्हें अपनी सामाजिक स्थिति को चुनौती देने वाली भक्त के रूप में याद किया जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-183","question":"According to Varkari tradition, Vitthal came to Pandharpur to see his devotee:","options":["Dhruva","Prahlada","Ambarisha","Pundalik"],"answer":3,"explanation":"The legend says that Vitthal came to Pandharpur to see Pundalik, who was so absorbed in serving his parents that he threw a brick for the god to stand on. The brick (vit) gives Vitthal his name.","difficulty":"moderate","questionHi":"वारकरी परंपरा के अनुसार विट्ठल पंढरपुर में अपने किस भक्त को देखने आए?","optionsHi":["ध्रुव","प्रह्लाद","अंबरीष","पुंडलिक"],"explanationHi":"कथा है कि विट्ठल पंढरपुर में पुंडलिक को देखने आए, जो माता-पिता की सेवा में इतना लीन था कि उसने देवता के खड़े होने के लिए ईंट फेंक दी। इसी ईंट (वीट) से विट्ठल नाम पड़ा।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-184","question":"Which Alvar was a Chera king who composed the Perumal Tirumozhi?","options":["Kulasekhara Alvar","Nammalvar","Tirumangai Alvar","Andal"],"answer":0,"explanation":"Kulasekhara Alvar, a Chera king, composed the Perumal Tirumozhi in praise of Vishnu and Rama. Nammalvar and Tirumangai were chieftains or scholars, and Andal was a woman saint.","difficulty":"hard","questionHi":"किस आळवार ने, जो चेर राजा थे, पेरुमाल तिरुमोऴि की रचना की?","optionsHi":["कुलशेखर आळवार","नम्माळवार","तिरुमंगै आळवार","आंडाल"],"explanationHi":"चेर राजा कुलशेखर आळवार ने विष्णु और राम की स्तुति में पेरुमाल तिरुमोऴि रचा। नम्माळवार और तिरुमंगै सरदार या विद्वान थे और आंडाल संत महिला थीं।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-185","question":"Vallalar (Ramalinga Swamigal), the 19th-century Tamil saint who founded the Sathya Gnana Sabha at Vadalur, emphasised:","options":["Revival of the Vedic sacrifices as the only path to liberation","Compassion for all beings and a casteless path (sanmarga)","Strict observance of caste purity in worship and temple entry","Conversion of Shaivas to Vaishnavism through temple worship"],"answer":1,"explanation":"Vallalar taught jiva karunya, compassion for all life, and a casteless path of universal brotherhood called the Samarasa Suddha Sanmarga. He opposed caste distinctions and animal sacrifice.","difficulty":"hard","questionHi":"19वीं शताब्दी के तमिल संत वल्लालार (रामलिंग स्वामी), जिन्होंने वडलूर में सत्य ज्ञान सभा स्थापित की, ने किस पर बल दिया?","optionsHi":["मोक्ष के एकमात्र मार्ग के रूप में वैदिक यज्ञों के पुनरुद्धार पर","सभी प्राणियों के प्रति करुणा और जातिविहीन मार्ग (सन्मार्ग) पर","उपासना और मंदिर-प्रवेश में जातीय शुद्धता के कठोर पालन पर","मंदिर-पूजा के माध्यम से शैवों के वैष्णव बनने पर"],"explanationHi":"वल्लालार ने जीवकारुण्य, यानी सभी प्राणियों के प्रति करुणा, और समरस शुद्ध सन्मार्ग नामक जातिविहीन सार्वभौमिक भाईचारे का मार्ग सिखाया। उन्होंने जाति-भेद और पशुबलि का विरोध किया।","source":"UPSC Prelims · State PCS"},
  {"id":"history-bhakti-sufi-186","question":"The Shikshapatri (1826), a code of conduct for followers, was written by:","options":["Swami Dayanand, founder of the Arya Samaj","Vallabhacharya, founder of the Pushtimarg","Swaminarayan (Sahajanand Swami)","Ramananda, the Ramanandi saint of Kashi"],"answer":2,"explanation":"Swaminarayan, also called Sahajanand Swami, composed the Shikshapatri in 1826 as a guide to conduct for his followers in Gujarat. He emphasised ahimsa, vegetarianism and moral discipline.","difficulty":"moderate","questionHi":"अनुयायियों के आचार-संहिता ग्रंथ शिक्षापत्री (1826) की रचना किसने की?","optionsHi":["स्वामी दयानंद, आर्य समाज के संस्थापक","वल्लभाचार्य, पुष्टिमार्ग के संस्थापक","स्वामीनारायण (सहजानंद स्वामी)","रामानंद, काशी के रामानंदी संत"],"explanationHi":"सहजानंद स्वामी के नाम से भी जाने जाने वाले स्वामीनारायण ने 1826 में गुजरात के अपने अनुयायियों के आचरण-मार्गदर्शन के रूप में शिक्षापत्री रची। उन्होंने अहिंसा, शाकाहार और नैतिक अनुशासन पर बल दिया।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-187","question":"The tradition of the Ramlila in Varanasi is traditionally credited to:","options":["Surdas","Kabir","Mirabai","Tulsidas"],"answer":3,"explanation":"Tradition credits Tulsidas with starting the Ramlila of Varanasi, in which the Ramcharitmanas is staged. The Ramlila became one of India's major folk theatre forms.","difficulty":"moderate","questionHi":"वाराणसी की रामलीला की परंपरा का श्रेय परंपरा से किसे दिया जाता है?","optionsHi":["सूरदास","कबीर","मीराबाई","तुलसीदास"],"explanationHi":"परंपरा वाराणसी की रामलीला शुरू करने का श्रेय तुलसीदास को देती है, जिसमें रामचरितमानस का मंचन होता है। रामलीला भारत की प्रमुख लोक-नाट्य शैलियों में से एक बनी।","source":"SSC CGL · State PCS"},
  {"id":"history-bhakti-sufi-188","question":"Which close companion of Chaitanya, born in a Muslim family, was known for chanting the divine name hundreds of thousands of times daily?","options":["Advaita Acharya","Nityananda","Srivasa Pandit","Haridasa Thakura"],"answer":3,"explanation":"Haridasa Thakura, said to have been born in a Muslim family, was one of Chaitanya's closest companions and a famed chanter of the Hare Krishna name. Advaita, Nityananda and Srivasa were Hindu associates of Chaitanya's Nadia circle.","difficulty":"very-hard","questionHi":"चैतन्य का वह निकट साथी कौन था जो मुस्लिम परिवार में जन्मा और प्रतिदिन लाखों बार भगवन्नाम जपने के लिए जाना जाता था?","optionsHi":["अद्वैत आचार्य","नित्यानंद","श्रीवास पंडित","हरिदास ठाकुर"],"explanationHi":"माना जाता है कि मुस्लिम परिवार में जन्मे हरिदास ठाकुर चैतन्य के निकटतम साथियों में और हरे कृष्ण नाम के प्रसिद्ध जापक थे। अद्वैत, नित्यानंद और श्रीवास चैतन्य के नदिया मंडल के हिंदू सहयोगी थे।","source":"UPSC Prelims · State PCS"},
];

